let QSTATS = {}; // computado dinamicamente por rodada/turma em recomputeSimDerived() via computeQStats()
const QCONTENT={"1":{"enunciado":"Leia o trecho: \"Ao ver Teseu, ela se impressionou com sua coragem, mas percebeu que apenas a força não seria suficiente para salvá-lo. O verdadeiro desafio não era somente derrotar o Minotauro: era escapar do labirinto.\"\n\nA construção desse trecho contribui para a narrativa ao","alt":{"A":"desvalorizar a coragem de Teseu, apresentando-o como incapaz de enfrentar o monstro.","B":"antecipar que a resolução do conflito dependeria da combinação entre coragem, planejamento e inteligência.","C":"indicar que Ariadne conhecia um caminho secreto que levava diretamente ao centro do labirinto.","D":"revelar que o Minotauro representava um perigo menor do que os jovens atenienses imaginavam."},"gabarito":"B","justificativa":"O trecho separa dois desafios: vencer o Minotauro (força) e escapar do labirinto (outra coisa). Essa distinção prepara o leitor para o resto da história, em que Teseu só consegue sair vivo porque usa o fio de Ariadne — ou seja, coragem sozinha não bastaria; foi preciso planejamento (o fio) e inteligência (usá-lo para voltar). As alternativas A, C e D contrariam o texto: em nenhum momento a coragem de Teseu é desvalorizada, Ariadne não conhecia um caminho secreto (ela deu um fio para marcar o caminho já percorrido) e o Minotauro é tratado como ameaça real, não menor.","passage":"Durante muitos anos, a cidade de Atenas viveu sob o domínio de uma terrível obrigação. Como punição por uma antiga derrota, os atenienses deveriam enviar regularmente sete rapazes e sete moças à ilha de Creta. Os jovens eram entregues ao Minotauro, criatura monstruosa que possuía corpo de homem e cabeça de touro.\n\nO monstro vivia no centro de um imenso labirinto construído por Dédalo, um arquiteto de extraordinária habilidade. Seus corredores eram tão numerosos e parecidos que qualquer pessoa que entrasse ali acabava se perdendo. Mesmo que alguém conseguisse derrotar o Minotauro, dificilmente encontraria o caminho de volta.\n\nQuando chegou o momento de enviar um novo grupo de jovens, Teseu, filho do rei Egeu, decidiu acompanhá-los. Ele não havia sido escolhido, mas se ofereceu voluntariamente porque desejava matar o monstro e libertar Atenas daquela obrigação.\n\nO rei tentou impedir a partida. Temia perder o filho no labirinto, como tantos outros jovens já haviam sido perdidos. Teseu, porém, não mudou de ideia. Antes da viagem, pai e filho fizeram um acordo: o navio partiria com velas negras, sinal da tristeza que acompanhava aquela missão. Caso Teseu retornasse vitorioso, deveria substituí-las por velas brancas. Assim, Egeu saberia, ainda de longe, que o filho continuava vivo.\n\nQuando os atenienses chegaram a Creta, foram conduzidos à presença do rei Minos. Entre as pessoas que observavam a chegada estava Ariadne, filha do rei. Ao ver Teseu, ela se impressionou com sua coragem, mas percebeu que apenas a força não seria suficiente para salvá-lo. O verdadeiro desafio não era somente derrotar o Minotauro: era escapar do labirinto.\n\nAriadne decidiu ajudá-lo. Antes que os jovens fossem levados para o sacrifício, entregou secretamente a Teseu um novelo de lã e uma espada.\n\n— Amarre uma das pontas deste fio na entrada — orientou ela. — Enquanto avançar, desenrole o novelo. Depois de enfrentar o monstro, bastará seguir o fio para encontrar a saída.\n\nTeseu agradeceu e prometeu levá-la consigo quando deixasse Creta.\n\nAo entrar no labirinto, ele amarrou a ponta do fio a uma pedra e começou a caminhar. Os corredores eram escuros, estreitos e silenciosos. Em alguns momentos, o herói tinha a impressão de passar pelo mesmo lugar. Entretanto, continuou desenrolando o fio, certo de que aquela frágil linha representava sua única ligação com o mundo exterior.\n\nDepois de caminhar por muito tempo, ouviu um rugido que fez as paredes estremecerem. No centro do labirinto, encontrou o Minotauro. A criatura avançou com violência, tentando atingi-lo com os chifres. Teseu desviou dos primeiros ataques e esperou o momento adequado para usar a espada. Após uma luta difícil, conseguiu vencer o monstro.\n\nA vitória, contudo, não significava que o perigo havia terminado. Cercado por passagens iguais, Teseu não sabia em qual direção seguir. Então se lembrou do novelo. Segurou o fio e percorreu lentamente o caminho inverso, até encontrar a saída. Os jovens atenienses o receberam com alegria, e todos fugiram de Creta com a ajuda de Ariadne.\n\nDurante a viagem de volta, porém, os acontecimentos tomaram um rumo inesperado. Ariadne foi deixada na ilha de Naxos. Algumas versões do mito afirmam que Teseu a abandonou; outras contam que os deuses determinaram a separação. Seja qual for a explicação, o herói continuou a viagem sem ela.\n\nAo se aproximar de Atenas, Teseu estava tão envolvido com tudo o que havia acontecido que se esqueceu da promessa feita ao pai. As velas negras não foram substituídas pelas brancas.\n\nDo alto de um penhasco, Egeu avistou o navio retornando. Ao ver as velas escuras, concluiu que o filho havia morrido. Dominado pelo desespero, lançou-se ao mar, que, segundo a tradição, passou a ser chamado de Mar Egeu.\n\nTeseu regressou como o herói que havia derrotado o Minotauro e libertado Atenas. Sua vitória, entretanto, foi acompanhada por uma perda irreparável. Ele descobriu que vencer uma batalha não impede que um descuido provoque consequências trágicas. No labirinto, havia encontrado o caminho de volta seguindo um fio; fora dele, porém, não conseguiu manter a ligação representada pela palavra dada ao pai.\n\nFonte: adaptação para fins didáticos baseada na versão da MultiRio.","passage_title":"Teseu e o labirinto do Minotauro","aviso":false,"conteudo":"Interpretação de trechos e sentido figurado"},"2":{"enunciado":"Leia o fragmento: \"Em alguns momentos, o herói tinha a impressão de passar pelo mesmo lugar. Entretanto, continuou desenrolando o fio, certo de que aquela frágil linha representava sua única ligação com o mundo exterior.\"\n\nNesse contexto, a expressão \"frágil linha\" possui sentido literal e simbólico porque o fio","alt":{"A":"era fisicamente delicado e representava a dependência de Teseu em relação às decisões do rei Minos.","B":"poderia romper-se facilmente e simbolizava a força física utilizada para vencer o Minotauro.","C":"marcava materialmente o caminho e representava a esperança de retorno e a ligação de Teseu com a liberdade.","D":"servia para prender o monstro e simbolizava o compromisso de Teseu com os jovens atenienses."},"gabarito":"C","justificativa":"\"Frágil linha\" tem sentido literal — é mesmo um fio fino, que pode se romper — e sentido simbólico: ele é a única coisa que liga Teseu ao mundo exterior, ou seja, à possibilidade de sair vivo e livre do labirinto. É por isso que a alternativa C está correta: junta o sentido concreto (marcar o caminho) com o sentido figurado (esperança de retorno e liberdade). As demais alternativas erram o sentido simbólico: o fio não tem relação com o rei Minos (A), não serve para vencer o Minotauro (isso foi feito com a espada, não com o fio — B), e não prende o monstro nem representa compromisso com os outros jovens (D).","passage":"Durante muitos anos, a cidade de Atenas viveu sob o domínio de uma terrível obrigação. Como punição por uma antiga derrota, os atenienses deveriam enviar regularmente sete rapazes e sete moças à ilha de Creta. Os jovens eram entregues ao Minotauro, criatura monstruosa que possuía corpo de homem e cabeça de touro.\n\nO monstro vivia no centro de um imenso labirinto construído por Dédalo, um arquiteto de extraordinária habilidade. Seus corredores eram tão numerosos e parecidos que qualquer pessoa que entrasse ali acabava se perdendo. Mesmo que alguém conseguisse derrotar o Minotauro, dificilmente encontraria o caminho de volta.\n\nQuando chegou o momento de enviar um novo grupo de jovens, Teseu, filho do rei Egeu, decidiu acompanhá-los. Ele não havia sido escolhido, mas se ofereceu voluntariamente porque desejava matar o monstro e libertar Atenas daquela obrigação.\n\nO rei tentou impedir a partida. Temia perder o filho no labirinto, como tantos outros jovens já haviam sido perdidos. Teseu, porém, não mudou de ideia. Antes da viagem, pai e filho fizeram um acordo: o navio partiria com velas negras, sinal da tristeza que acompanhava aquela missão. Caso Teseu retornasse vitorioso, deveria substituí-las por velas brancas. Assim, Egeu saberia, ainda de longe, que o filho continuava vivo.\n\nQuando os atenienses chegaram a Creta, foram conduzidos à presença do rei Minos. Entre as pessoas que observavam a chegada estava Ariadne, filha do rei. Ao ver Teseu, ela se impressionou com sua coragem, mas percebeu que apenas a força não seria suficiente para salvá-lo. O verdadeiro desafio não era somente derrotar o Minotauro: era escapar do labirinto.\n\nAriadne decidiu ajudá-lo. Antes que os jovens fossem levados para o sacrifício, entregou secretamente a Teseu um novelo de lã e uma espada.\n\n— Amarre uma das pontas deste fio na entrada — orientou ela. — Enquanto avançar, desenrole o novelo. Depois de enfrentar o monstro, bastará seguir o fio para encontrar a saída.\n\nTeseu agradeceu e prometeu levá-la consigo quando deixasse Creta.\n\nAo entrar no labirinto, ele amarrou a ponta do fio a uma pedra e começou a caminhar. Os corredores eram escuros, estreitos e silenciosos. Em alguns momentos, o herói tinha a impressão de passar pelo mesmo lugar. Entretanto, continuou desenrolando o fio, certo de que aquela frágil linha representava sua única ligação com o mundo exterior.\n\nDepois de caminhar por muito tempo, ouviu um rugido que fez as paredes estremecerem. No centro do labirinto, encontrou o Minotauro. A criatura avançou com violência, tentando atingi-lo com os chifres. Teseu desviou dos primeiros ataques e esperou o momento adequado para usar a espada. Após uma luta difícil, conseguiu vencer o monstro.\n\nA vitória, contudo, não significava que o perigo havia terminado. Cercado por passagens iguais, Teseu não sabia em qual direção seguir. Então se lembrou do novelo. Segurou o fio e percorreu lentamente o caminho inverso, até encontrar a saída. Os jovens atenienses o receberam com alegria, e todos fugiram de Creta com a ajuda de Ariadne.\n\nDurante a viagem de volta, porém, os acontecimentos tomaram um rumo inesperado. Ariadne foi deixada na ilha de Naxos. Algumas versões do mito afirmam que Teseu a abandonou; outras contam que os deuses determinaram a separação. Seja qual for a explicação, o herói continuou a viagem sem ela.\n\nAo se aproximar de Atenas, Teseu estava tão envolvido com tudo o que havia acontecido que se esqueceu da promessa feita ao pai. As velas negras não foram substituídas pelas brancas.\n\nDo alto de um penhasco, Egeu avistou o navio retornando. Ao ver as velas escuras, concluiu que o filho havia morrido. Dominado pelo desespero, lançou-se ao mar, que, segundo a tradição, passou a ser chamado de Mar Egeu.\n\nTeseu regressou como o herói que havia derrotado o Minotauro e libertado Atenas. Sua vitória, entretanto, foi acompanhada por uma perda irreparável. Ele descobriu que vencer uma batalha não impede que um descuido provoque consequências trágicas. No labirinto, havia encontrado o caminho de volta seguindo um fio; fora dele, porém, não conseguiu manter a ligação representada pela palavra dada ao pai.\n\nFonte: adaptação para fins didáticos baseada na versão da MultiRio.","passage_title":"Teseu e o labirinto do Minotauro","aviso":false,"conteudo":"Interpretação de trechos e sentido figurado"},"3":{"enunciado":"Observe a relação entre os trechos:\n\"Depois de enfrentar o monstro, bastará seguir o fio para encontrar a saída.\"\n\"As velas negras não foram substituídas pelas brancas.\"\n\nA comparação entre essas duas situações evidencia que Teseu","alt":{"A":"seguiu corretamente todas as orientações recebidas ao longo da viagem.","B":"demonstrou maior preocupação com a promessa feita ao pai do que com sua própria sobrevivência.","C":"soube preservar uma ligação material necessária para sobreviver, mas não manteve o compromisso simbolizado pelas velas.","D":"esqueceu-se tanto do fio de Ariadne quanto da troca das velas combinada com Egeu."},"gabarito":"C","justificativa":"O primeiro trecho mostra Teseu seguindo o fio com sucesso (ligação material que ele mantém até o fim). O segundo mostra que ele esqueceu de trocar as velas (compromisso simbólico com o pai, que ele não cumpre). A alternativa C é a única que capta esse contraste exato: ele preservou uma coisa (o fio) e falhou em outra (a promessa das velas). A é falsa porque ele não seguiu todas as orientações — esqueceu das velas. B inverte a lógica do texto (foi o contrário: ele lembrou do fio, mas não da promessa). D está errada porque ele não esqueceu do fio, só das velas.","passage":"Durante muitos anos, a cidade de Atenas viveu sob o domínio de uma terrível obrigação. Como punição por uma antiga derrota, os atenienses deveriam enviar regularmente sete rapazes e sete moças à ilha de Creta. Os jovens eram entregues ao Minotauro, criatura monstruosa que possuía corpo de homem e cabeça de touro.\n\nO monstro vivia no centro de um imenso labirinto construído por Dédalo, um arquiteto de extraordinária habilidade. Seus corredores eram tão numerosos e parecidos que qualquer pessoa que entrasse ali acabava se perdendo. Mesmo que alguém conseguisse derrotar o Minotauro, dificilmente encontraria o caminho de volta.\n\nQuando chegou o momento de enviar um novo grupo de jovens, Teseu, filho do rei Egeu, decidiu acompanhá-los. Ele não havia sido escolhido, mas se ofereceu voluntariamente porque desejava matar o monstro e libertar Atenas daquela obrigação.\n\nO rei tentou impedir a partida. Temia perder o filho no labirinto, como tantos outros jovens já haviam sido perdidos. Teseu, porém, não mudou de ideia. Antes da viagem, pai e filho fizeram um acordo: o navio partiria com velas negras, sinal da tristeza que acompanhava aquela missão. Caso Teseu retornasse vitorioso, deveria substituí-las por velas brancas. Assim, Egeu saberia, ainda de longe, que o filho continuava vivo.\n\nQuando os atenienses chegaram a Creta, foram conduzidos à presença do rei Minos. Entre as pessoas que observavam a chegada estava Ariadne, filha do rei. Ao ver Teseu, ela se impressionou com sua coragem, mas percebeu que apenas a força não seria suficiente para salvá-lo. O verdadeiro desafio não era somente derrotar o Minotauro: era escapar do labirinto.\n\nAriadne decidiu ajudá-lo. Antes que os jovens fossem levados para o sacrifício, entregou secretamente a Teseu um novelo de lã e uma espada.\n\n— Amarre uma das pontas deste fio na entrada — orientou ela. — Enquanto avançar, desenrole o novelo. Depois de enfrentar o monstro, bastará seguir o fio para encontrar a saída.\n\nTeseu agradeceu e prometeu levá-la consigo quando deixasse Creta.\n\nAo entrar no labirinto, ele amarrou a ponta do fio a uma pedra e começou a caminhar. Os corredores eram escuros, estreitos e silenciosos. Em alguns momentos, o herói tinha a impressão de passar pelo mesmo lugar. Entretanto, continuou desenrolando o fio, certo de que aquela frágil linha representava sua única ligação com o mundo exterior.\n\nDepois de caminhar por muito tempo, ouviu um rugido que fez as paredes estremecerem. No centro do labirinto, encontrou o Minotauro. A criatura avançou com violência, tentando atingi-lo com os chifres. Teseu desviou dos primeiros ataques e esperou o momento adequado para usar a espada. Após uma luta difícil, conseguiu vencer o monstro.\n\nA vitória, contudo, não significava que o perigo havia terminado. Cercado por passagens iguais, Teseu não sabia em qual direção seguir. Então se lembrou do novelo. Segurou o fio e percorreu lentamente o caminho inverso, até encontrar a saída. Os jovens atenienses o receberam com alegria, e todos fugiram de Creta com a ajuda de Ariadne.\n\nDurante a viagem de volta, porém, os acontecimentos tomaram um rumo inesperado. Ariadne foi deixada na ilha de Naxos. Algumas versões do mito afirmam que Teseu a abandonou; outras contam que os deuses determinaram a separação. Seja qual for a explicação, o herói continuou a viagem sem ela.\n\nAo se aproximar de Atenas, Teseu estava tão envolvido com tudo o que havia acontecido que se esqueceu da promessa feita ao pai. As velas negras não foram substituídas pelas brancas.\n\nDo alto de um penhasco, Egeu avistou o navio retornando. Ao ver as velas escuras, concluiu que o filho havia morrido. Dominado pelo desespero, lançou-se ao mar, que, segundo a tradição, passou a ser chamado de Mar Egeu.\n\nTeseu regressou como o herói que havia derrotado o Minotauro e libertado Atenas. Sua vitória, entretanto, foi acompanhada por uma perda irreparável. Ele descobriu que vencer uma batalha não impede que um descuido provoque consequências trágicas. No labirinto, havia encontrado o caminho de volta seguindo um fio; fora dele, porém, não conseguiu manter a ligação representada pela palavra dada ao pai.\n\nFonte: adaptação para fins didáticos baseada na versão da MultiRio.","passage_title":"Teseu e o labirinto do Minotauro","aviso":false,"conteudo":"Relações entre trechos (comparação e causa)"},"4":{"enunciado":"Leia: \"Ao ver as velas escuras, concluiu que o filho havia morrido. Dominado pelo desespero, lançou-se ao mar [...].\"\n\nA partir do trecho e das informações anteriores da narrativa, pode-se concluir que o desfecho trágico foi provocado","alt":{"A":"exclusivamente pela decisão impulsiva de Egeu, pois Teseu não havia assumido qualquer compromisso com o pai.","B":"somente pelo esquecimento de Teseu, uma vez que Egeu não tinha outra possibilidade de interpretar o sinal recebido.","C":"pela combinação entre o descuido de Teseu, que não trocou as velas, e a atitude precipitada de Egeu diante do sinal.","D":"pela intenção de Teseu de esconder do pai os acontecimentos ocorridos durante a viagem."},"gabarito":"C","justificativa":"A tragédia tem duas causas encadeadas: Teseu esqueceu de trocar as velas (descuido) e Egeu, ao ver as velas negras, presumiu o pior e se lançou ao mar sem esperar confirmação (atitude precipitada). A alternativa C é a única que reconhece essa dupla responsabilidade. A e B erram por tratar a causa como única (exclusivamente/somente), quando o texto deixa claro que os dois fatores se combinaram. D não tem apoio no texto: não há indício de que Teseu quisesse esconder algo de propósito, apenas que esqueceu.","passage":"Durante muitos anos, a cidade de Atenas viveu sob o domínio de uma terrível obrigação. Como punição por uma antiga derrota, os atenienses deveriam enviar regularmente sete rapazes e sete moças à ilha de Creta. Os jovens eram entregues ao Minotauro, criatura monstruosa que possuía corpo de homem e cabeça de touro.\n\nO monstro vivia no centro de um imenso labirinto construído por Dédalo, um arquiteto de extraordinária habilidade. Seus corredores eram tão numerosos e parecidos que qualquer pessoa que entrasse ali acabava se perdendo. Mesmo que alguém conseguisse derrotar o Minotauro, dificilmente encontraria o caminho de volta.\n\nQuando chegou o momento de enviar um novo grupo de jovens, Teseu, filho do rei Egeu, decidiu acompanhá-los. Ele não havia sido escolhido, mas se ofereceu voluntariamente porque desejava matar o monstro e libertar Atenas daquela obrigação.\n\nO rei tentou impedir a partida. Temia perder o filho no labirinto, como tantos outros jovens já haviam sido perdidos. Teseu, porém, não mudou de ideia. Antes da viagem, pai e filho fizeram um acordo: o navio partiria com velas negras, sinal da tristeza que acompanhava aquela missão. Caso Teseu retornasse vitorioso, deveria substituí-las por velas brancas. Assim, Egeu saberia, ainda de longe, que o filho continuava vivo.\n\nQuando os atenienses chegaram a Creta, foram conduzidos à presença do rei Minos. Entre as pessoas que observavam a chegada estava Ariadne, filha do rei. Ao ver Teseu, ela se impressionou com sua coragem, mas percebeu que apenas a força não seria suficiente para salvá-lo. O verdadeiro desafio não era somente derrotar o Minotauro: era escapar do labirinto.\n\nAriadne decidiu ajudá-lo. Antes que os jovens fossem levados para o sacrifício, entregou secretamente a Teseu um novelo de lã e uma espada.\n\n— Amarre uma das pontas deste fio na entrada — orientou ela. — Enquanto avançar, desenrole o novelo. Depois de enfrentar o monstro, bastará seguir o fio para encontrar a saída.\n\nTeseu agradeceu e prometeu levá-la consigo quando deixasse Creta.\n\nAo entrar no labirinto, ele amarrou a ponta do fio a uma pedra e começou a caminhar. Os corredores eram escuros, estreitos e silenciosos. Em alguns momentos, o herói tinha a impressão de passar pelo mesmo lugar. Entretanto, continuou desenrolando o fio, certo de que aquela frágil linha representava sua única ligação com o mundo exterior.\n\nDepois de caminhar por muito tempo, ouviu um rugido que fez as paredes estremecerem. No centro do labirinto, encontrou o Minotauro. A criatura avançou com violência, tentando atingi-lo com os chifres. Teseu desviou dos primeiros ataques e esperou o momento adequado para usar a espada. Após uma luta difícil, conseguiu vencer o monstro.\n\nA vitória, contudo, não significava que o perigo havia terminado. Cercado por passagens iguais, Teseu não sabia em qual direção seguir. Então se lembrou do novelo. Segurou o fio e percorreu lentamente o caminho inverso, até encontrar a saída. Os jovens atenienses o receberam com alegria, e todos fugiram de Creta com a ajuda de Ariadne.\n\nDurante a viagem de volta, porém, os acontecimentos tomaram um rumo inesperado. Ariadne foi deixada na ilha de Naxos. Algumas versões do mito afirmam que Teseu a abandonou; outras contam que os deuses determinaram a separação. Seja qual for a explicação, o herói continuou a viagem sem ela.\n\nAo se aproximar de Atenas, Teseu estava tão envolvido com tudo o que havia acontecido que se esqueceu da promessa feita ao pai. As velas negras não foram substituídas pelas brancas.\n\nDo alto de um penhasco, Egeu avistou o navio retornando. Ao ver as velas escuras, concluiu que o filho havia morrido. Dominado pelo desespero, lançou-se ao mar, que, segundo a tradição, passou a ser chamado de Mar Egeu.\n\nTeseu regressou como o herói que havia derrotado o Minotauro e libertado Atenas. Sua vitória, entretanto, foi acompanhada por uma perda irreparável. Ele descobriu que vencer uma batalha não impede que um descuido provoque consequências trágicas. No labirinto, havia encontrado o caminho de volta seguindo um fio; fora dele, porém, não conseguiu manter a ligação representada pela palavra dada ao pai.\n\nFonte: adaptação para fins didáticos baseada na versão da MultiRio.","passage_title":"Teseu e o labirinto do Minotauro","aviso":false,"conteudo":"Relações entre trechos (comparação e causa)"},"5":{"enunciado":"Leia o último período do texto: \"No labirinto, havia encontrado o caminho de volta seguindo um fio; fora dele, porém, não conseguiu manter a ligação representada pela palavra dada ao pai.\"\n\nA oposição entre \"no labirinto\" e \"fora dele\" permite interpretar que","alt":{"A":"os desafios físicos são sempre mais difíceis do que os conflitos afetivos e morais.","B":"Teseu conseguiu superar um espaço perigoso, mas falhou ao cumprir uma responsabilidade pessoal.","C":"o fio de Ariadne deveria ter sido utilizado também para orientar o navio até Atenas.","D":"a promessa feita a Egeu perdeu sua importância depois que o Minotauro foi derrotado."},"gabarito":"B","justificativa":"O período final resume toda a moral da história: dentro do labirinto (desafio físico) Teseu venceu; fora dele (no plano da palavra dada, do compromisso pessoal) ele fracassou. A alternativa B expressa exatamente essa síntese. A generaliza demais (\"sempre\") algo que o texto mostra apenas nesse caso específico. C e D não têm base textual: o fio nunca teve relação com a navegação de volta, e nada indica que a promessa \"perdeu importância\" — pelo contrário, o texto trata o esquecimento como uma falha grave.","passage":"Durante muitos anos, a cidade de Atenas viveu sob o domínio de uma terrível obrigação. Como punição por uma antiga derrota, os atenienses deveriam enviar regularmente sete rapazes e sete moças à ilha de Creta. Os jovens eram entregues ao Minotauro, criatura monstruosa que possuía corpo de homem e cabeça de touro.\n\nO monstro vivia no centro de um imenso labirinto construído por Dédalo, um arquiteto de extraordinária habilidade. Seus corredores eram tão numerosos e parecidos que qualquer pessoa que entrasse ali acabava se perdendo. Mesmo que alguém conseguisse derrotar o Minotauro, dificilmente encontraria o caminho de volta.\n\nQuando chegou o momento de enviar um novo grupo de jovens, Teseu, filho do rei Egeu, decidiu acompanhá-los. Ele não havia sido escolhido, mas se ofereceu voluntariamente porque desejava matar o monstro e libertar Atenas daquela obrigação.\n\nO rei tentou impedir a partida. Temia perder o filho no labirinto, como tantos outros jovens já haviam sido perdidos. Teseu, porém, não mudou de ideia. Antes da viagem, pai e filho fizeram um acordo: o navio partiria com velas negras, sinal da tristeza que acompanhava aquela missão. Caso Teseu retornasse vitorioso, deveria substituí-las por velas brancas. Assim, Egeu saberia, ainda de longe, que o filho continuava vivo.\n\nQuando os atenienses chegaram a Creta, foram conduzidos à presença do rei Minos. Entre as pessoas que observavam a chegada estava Ariadne, filha do rei. Ao ver Teseu, ela se impressionou com sua coragem, mas percebeu que apenas a força não seria suficiente para salvá-lo. O verdadeiro desafio não era somente derrotar o Minotauro: era escapar do labirinto.\n\nAriadne decidiu ajudá-lo. Antes que os jovens fossem levados para o sacrifício, entregou secretamente a Teseu um novelo de lã e uma espada.\n\n— Amarre uma das pontas deste fio na entrada — orientou ela. — Enquanto avançar, desenrole o novelo. Depois de enfrentar o monstro, bastará seguir o fio para encontrar a saída.\n\nTeseu agradeceu e prometeu levá-la consigo quando deixasse Creta.\n\nAo entrar no labirinto, ele amarrou a ponta do fio a uma pedra e começou a caminhar. Os corredores eram escuros, estreitos e silenciosos. Em alguns momentos, o herói tinha a impressão de passar pelo mesmo lugar. Entretanto, continuou desenrolando o fio, certo de que aquela frágil linha representava sua única ligação com o mundo exterior.\n\nDepois de caminhar por muito tempo, ouviu um rugido que fez as paredes estremecerem. No centro do labirinto, encontrou o Minotauro. A criatura avançou com violência, tentando atingi-lo com os chifres. Teseu desviou dos primeiros ataques e esperou o momento adequado para usar a espada. Após uma luta difícil, conseguiu vencer o monstro.\n\nA vitória, contudo, não significava que o perigo havia terminado. Cercado por passagens iguais, Teseu não sabia em qual direção seguir. Então se lembrou do novelo. Segurou o fio e percorreu lentamente o caminho inverso, até encontrar a saída. Os jovens atenienses o receberam com alegria, e todos fugiram de Creta com a ajuda de Ariadne.\n\nDurante a viagem de volta, porém, os acontecimentos tomaram um rumo inesperado. Ariadne foi deixada na ilha de Naxos. Algumas versões do mito afirmam que Teseu a abandonou; outras contam que os deuses determinaram a separação. Seja qual for a explicação, o herói continuou a viagem sem ela.\n\nAo se aproximar de Atenas, Teseu estava tão envolvido com tudo o que havia acontecido que se esqueceu da promessa feita ao pai. As velas negras não foram substituídas pelas brancas.\n\nDo alto de um penhasco, Egeu avistou o navio retornando. Ao ver as velas escuras, concluiu que o filho havia morrido. Dominado pelo desespero, lançou-se ao mar, que, segundo a tradição, passou a ser chamado de Mar Egeu.\n\nTeseu regressou como o herói que havia derrotado o Minotauro e libertado Atenas. Sua vitória, entretanto, foi acompanhada por uma perda irreparável. Ele descobriu que vencer uma batalha não impede que um descuido provoque consequências trágicas. No labirinto, havia encontrado o caminho de volta seguindo um fio; fora dele, porém, não conseguiu manter a ligação representada pela palavra dada ao pai.\n\nFonte: adaptação para fins didáticos baseada na versão da MultiRio.","passage_title":"Teseu e o labirinto do Minotauro","aviso":false,"conteudo":"Relações entre trechos (comparação e causa)"},"6":{"enunciado":"Qual é a principal característica do Dr. Simão Bacamarte apresentada no texto?","alt":{"A":"Vaidoso e preguiçoso","B":"Obstinado, metódico","C":"Medroso e indeciso","D":"Alegre e brincalhão"},"gabarito":"B","justificativa":"O texto descreve Bacamarte explicitamente: \"Bacamarte era obstinado, metódico e não admitia dúvidas.\" A alternativa B repete essas palavras quase literalmente. As demais características (vaidoso, preguiçoso, medroso, indeciso, alegre, brincalhão) não aparecem em nenhum momento do trecho — são o oposto do que é descrito, já que ele é apresentado como um homem de ciência, seguro de si e dedicado.","passage":"Itaguaí era uma vila pacata, sonolenta e provinciana, onde nada acontecia de extraordinário. Foi nesse cenário modesto que o Dr. Simão Bacamarte decidiu fundar a Casa Verde, o primeiro hospício do Brasil. Homem de ciência, educado na Europa, ele voltou para sua terra natal com uma missão ambiciosa: estudar a loucura em todas as suas manifestações. Para a população, a ideia parecia absurda. Mas Bacamarte era obstinado, metódico e não admitia dúvidas. Ele acreditava que a razão e a observação científica poderiam desvendar os mistérios da mente humana.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Interpretação de texto literário"},"7":{"enunciado":"No trecho \"vila pacata, sonolenta e provinciana\", os adjetivos servem para:","alt":{"A":"Indicar ação do sujeito","B":"Ligar duas orações","C":"Substituir o nome \"vila\"","D":"Caracterizar a vila de Itaguaí"},"gabarito":"D","justificativa":"\"Pacata\", \"sonolenta\" e \"provinciana\" são adjetivos que atribuem qualidades ao substantivo \"vila\" — função clássica de caracterização. A alternativa D é a definição correta da função do adjetivo. A está errada porque adjetivo não indica ação (isso é papel do verbo); B está errada porque quem liga orações são conjunções, não adjetivos; C está errada porque o adjetivo não substitui o substantivo, ele o acompanha e qualifica (quem substitui um nome é o pronome).","passage":"Itaguaí era uma vila pacata, sonolenta e provinciana, onde nada acontecia de extraordinário. Foi nesse cenário modesto que o Dr. Simão Bacamarte decidiu fundar a Casa Verde, o primeiro hospício do Brasil. Homem de ciência, educado na Europa, ele voltou para sua terra natal com uma missão ambiciosa: estudar a loucura em todas as suas manifestações. Para a população, a ideia parecia absurda. Mas Bacamarte era obstinado, metódico e não admitia dúvidas. Ele acreditava que a razão e a observação científica poderiam desvendar os mistérios da mente humana.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Morfologia (adjetivos e pronomes)"},"8":{"enunciado":"No trecho \"A Casa Verde cresceu rapidamente\", o verbo \"cresceu\" está no:","alt":{"A":"Presente do indicativo","B":"Pretérito perfeito do indicativo","C":"Futuro do presente","D":"Imperativo"},"gabarito":"B","justificativa":"\"Cresceu\" indica uma ação já concluída no passado — a forma típica do pretérito perfeito do indicativo (eu cresci, ele cresceu). É diferente do presente (\"cresce\"), do futuro (\"crescerá\") e do imperativo, que é usado para ordens (\"cresça!\"). Por isso a alternativa correta é B.","passage":"A Casa Verde cresceu rapidamente. Primeiro entraram os loucos furiosos, depois os melancólicos, depois os que falavam sozinhos. A cidade inteira comentava o caso. \"O barbeiro Porfírio é doido\", diziam uns. O próprio Bacamarte começou a duvidar do seu próprio critério. Será que a loucura era a exceção ou a regra? Ele, que era tão seguro, passou a observar a si mesmo com desconfiança. A ciência que antes lhe dava certezas agora lhe trazia perguntas.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Sintaxe e verbos"},"9":{"enunciado":"Em \"Ele, que era tão seguro, passou a observar a si mesmo\", o pronome \"si\" refere-se a:","alt":{"A":"Porfírio","B":"D. Evarista","C":"Dr. Simão Bacamarte","D":"Narrador"},"gabarito":"C","justificativa":"O pronome reflexivo \"si\" remete ao sujeito da própria oração — \"Ele\", que no contexto do parágrafo é o Dr. Simão Bacamarte, observando a si próprio com desconfiança. É um caso clássico de pronome reflexivo: o sujeito pratica e recebe a ação ao mesmo tempo (ele observa ele mesmo). Porfírio e D. Evarista são citados em outras partes do conto, mas não são o sujeito desta oração; o narrador não é personagem da história, então não pode ser o referente de um pronome reflexivo dentro da narrativa.","passage":"A Casa Verde cresceu rapidamente. Primeiro entraram os loucos furiosos, depois os melancólicos, depois os que falavam sozinhos. A cidade inteira comentava o caso. \"O barbeiro Porfírio é doido\", diziam uns. O próprio Bacamarte começou a duvidar do seu próprio critério. Será que a loucura era a exceção ou a regra? Ele, que era tão seguro, passou a observar a si mesmo com desconfiança. A ciência que antes lhe dava certezas agora lhe trazia perguntas.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Morfologia (adjetivos e pronomes)"},"10":{"enunciado":"A \"ideia revolucionária\" de Bacamarte mostra qual crítica de Machado?","alt":{"A":"Crítica ao excesso de religião na cidade","B":"Crítica à ciência que se acha dona da verdade e classifica as pessoas","C":"Crítica à falta de médicos no Brasil","D":"Crítica aos políticos de Itaguaí"},"gabarito":"B","justificativa":"Ao inverter completamente sua teoria (prender os \"normais\" e soltar os \"loucos\") sem nunca duvidar de si mesmo, Bacamarte representa a crítica de Machado de Assis a uma ciência que se considera infalível e usa esse suposto rigor para classificar e controlar as pessoas — mesmo quando os critérios mudam de um extremo ao outro. A alternativa B é a única que capta essa ironia central do conto. As outras alternativas trazem temas (religião, falta de médicos, política) que não são o alvo da crítica nesse trecho.","passage":"Após encher a Casa Verde, Bacamarte teve uma ideia revolucionária: e se os normais fossem os doidos? Ele inverteu todo o seu estudo. Mandou soltar os internados e começou a prender as pessoas \"equilibradas\" de Itaguaí. Foi um caos. Pessoas respeitáveis, trabalhadores, mães de família foram levadas para dentro do hospício. A cidade entrou em pânico. O próprio vereador, o padre e o boticário foram parar lá dentro. A teoria do médico era simples e aterrorizante: normal é quem tem um desequilíbrio mínimo.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Interpretação de texto literário"},"11":{"enunciado":"Assinale a alternativa que apresenta um período simples:","alt":{"A":"\"Ele inverteu todo o seu estudo e mandou soltar os internados.\"","B":"\"A cidade entrou em pânico.\"","C":"\"Pessoas foram levadas para dentro porque eram normais.\"","D":"\"Quando ele teve a ideia, a cidade ficou em choque.\""},"gabarito":"B","justificativa":"Período simples é aquele com apenas um verbo (uma única oração). Em B, \"A cidade entrou em pânico\" há só um verbo (entrou), logo é período simples. Em A há dois verbos (inverteu / mandou), formando período composto por coordenação. Em C há dois verbos (foram levadas / eram), com uma oração subordinada causal. Em D há dois verbos (teve / ficou), com uma oração subordinada temporal. Por isso a resposta é B.","passage":"Após encher a Casa Verde, Bacamarte teve uma ideia revolucionária: e se os normais fossem os doidos? Ele inverteu todo o seu estudo. Mandou soltar os internados e começou a prender as pessoas \"equilibradas\" de Itaguaí. Foi um caos. Pessoas respeitáveis, trabalhadores, mães de família foram levadas para dentro do hospício. A cidade entrou em pânico. O próprio vereador, o padre e o boticário foram parar lá dentro. A teoria do médico era simples e aterrorizante: normal é quem tem um desequilíbrio mínimo.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Sintaxe e verbos"},"12":{"enunciado":"O final do conto sugere que:","alt":{"A":"A loucura foi totalmente curada pela ciência","B":"A sociedade prefere a normalidade e o silêncio a questionar a si mesma","C":"D. Evarista salvou o marido","D":"Itaguaí virou uma capital"},"gabarito":"B","justificativa":"No final, Bacamarte se declara \"curado\", tudo volta ao normal e \"ninguém mais falou em ciência\" — ou seja, a cidade prefere voltar à rotina pacata e não continuar questionando as ideias inquietantes que ele havia levantado sobre o que é loucura e o que é normalidade. Isso é o que a alternativa B expressa. A está errada porque o texto não trata de \"cura da loucura\" de forma literal e científica, e sim de um retorno à ordem social. C e D não têm nenhum apoio no texto.","passage":"No final, depois de estudar a si mesmo por meses, Bacamarte chegou a uma conclusão devastadora: ele era o único louco de Itaguaí. Ele, o homem mais lúcido, mais estudado, mais racional. Ele se internou voluntariamente na Casa Verde. Ficou lá por quatro meses. Quando saiu, estava \"curado\". Voltou a ser o marido dedicado de D. Evarista e o médico respeitado. Itaguaí voltou a ser pacata. E ninguém mais falou em ciência.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Interpretação de texto literário"},"13":{"enunciado":"Em \"o homem mais lúcido, mais estudado, mais racional\", os adjetivos estão no grau:","alt":{"A":"Positivo","B":"Comparativo de superioridade","C":"Comparativo de igualdade","D":"Superlativo absoluto"},"gabarito":"B","justificativa":"A estrutura \"mais + adjetivo\" indica comparação de superioridade (ele é mais lúcido do que os outros, mais estudado do que os outros). Por isso a resposta é B. Não é grau positivo (que seria só \"lúcido\", sem comparação), não é comparativo de igualdade (que usaria \"tão... quanto\"), e não é superlativo absoluto (que seria algo como \"lucidíssimo\").","passage":"No final, depois de estudar a si mesmo por meses, Bacamarte chegou a uma conclusão devastadora: ele era o único louco de Itaguaí. Ele, o homem mais lúcido, mais estudado, mais racional. Ele se internou voluntariamente na Casa Verde. Ficou lá por quatro meses. Quando saiu, estava \"curado\". Voltou a ser o marido dedicado de D. Evarista e o médico respeitado. Itaguaí voltou a ser pacata. E ninguém mais falou em ciência.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Morfologia (adjetivos e pronomes)"},"14":{"enunciado":"Em \"Quando saiu, estava 'curado'\", o sujeito oculto do verbo \"saiu\" é:","alt":{"A":"Itaguaí","B":"D. Evarista","C":"Dr. Simão Bacamarte","D":"A Casa Verde"},"gabarito":"C","justificativa":"O parágrafo inteiro fala da internação voluntária de Bacamarte na Casa Verde e do momento em que ele deixa o hospício — é ele quem \"saiu\" e está \"curado\". O sujeito está oculto (elíptico) porque já foi mencionado nas frases anteriores, mas o contexto deixa claro que se trata do Dr. Simão Bacamarte, não das outras opções, que são apenas lugares ou outras personagens citadas no texto.","passage":"No final, depois de estudar a si mesmo por meses, Bacamarte chegou a uma conclusão devastadora: ele era o único louco de Itaguaí. Ele, o homem mais lúcido, mais estudado, mais racional. Ele se internou voluntariamente na Casa Verde. Ficou lá por quatro meses. Quando saiu, estava \"curado\". Voltou a ser o marido dedicado de D. Evarista e o médico respeitado. Itaguaí voltou a ser pacata. E ninguém mais falou em ciência.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Sintaxe e verbos"},"15":{"enunciado":"Qual é o tema central de O Alienista?","alt":{"A":"Uma história de amor entre Bacamarte e D. Evarista","B":"A fundação do primeiro hospital do Brasil","C":"A relatividade dos conceitos de normalidade e loucura","D":"A vida pacata de uma cidade do interior"},"gabarito":"C","justificativa":"Toda a trama gira em torno de Bacamarte tentando definir cientificamente o que é loucura, mudando radicalmente seus critérios (de \"loucos são os diferentes\" para \"loucos são os normais\" e, por fim, \"o único louco sou eu\"). Isso evidencia que a obra discute como os limites entre normalidade e loucura são construções relativas, não verdades fixas — o que torna C o tema central. As demais alternativas descrevem elementos secundários da trama (um cenário, um evento pontual), não o assunto principal discutido pela obra.","passage":"No final, depois de estudar a si mesmo por meses, Bacamarte chegou a uma conclusão devastadora: ele era o único louco de Itaguaí. Ele, o homem mais lúcido, mais estudado, mais racional. Ele se internou voluntariamente na Casa Verde. Ficou lá por quatro meses. Quando saiu, estava \"curado\". Voltou a ser o marido dedicado de D. Evarista e o médico respeitado. Itaguaí voltou a ser pacata. E ninguém mais falou em ciência.","passage_title":"O Alienista (adaptação)","aviso":false,"conteudo":"Interpretação de texto literário"},"16":{"enunciado":"Uma prestadora de serviços cobra pela visita à residência do cliente e pelo tempo necessário para realizar o serviço na residência.\nO valor da visita é R$ 40 e o valor da hora para realização do serviço é R$ 20.\nUma expressão que indica o valor a ser pago (P) em função das horas (h) necessárias à execução do serviço é:","alt":{"A":"P = 40h","B":"P = 60h","C":"P = 20 + 40h","D":"P = 40 + 20h"},"gabarito":"D","justificativa":"Há uma parte fixa (a visita, R$ 40, cobrada independentemente do tempo) e uma parte variável (R$ 20 por hora trabalhada, ou seja, 20h). O valor total é a soma das duas partes: P = 40 + 20h. As demais alternativas ou esquecem a parte fixa (A e B) ou trocam os valores de visita e hora (C).","passage":null,"passage_title":null,"aviso":false,"conteudo":"Funções do 1º grau (afim)"},"17":{"enunciado":"Julgue as afirmativas a seguir sobre a função f(x) = 2x − 3. Podemos afirmar que:\nI – O coeficiente angular é 2.\nII – O coeficiente linear é 3.\nIII – A imagem da função para x = 1 é -1.\nDe acordo com o julgamento das afirmativas, é correto afirmar que:","alt":{"A":"Somente I é verdadeira.","B":"Somente I e II são verdadeiras.","C":"Somente III é verdadeira.","D":"Somente I e III são verdadeiras."},"gabarito":"D","justificativa":"Numa função do 1º grau f(x) = ax + b, \"a\" é o coeficiente angular e \"b\" o coeficiente linear. Aqui a = 2 e b = −3. A afirmativa I está correta (coeficiente angular é 2). A II está errada: o coeficiente linear é −3, não 3. Para a III, calcula-se f(1) = 2(1) − 3 = −1, o que confirma a afirmativa. Logo, I e III são verdadeiras e II é falsa, o que corresponde à alternativa D.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Funções do 1º grau (afim)"},"18":{"enunciado":"O lucro mensal L(x), em milhares de reais, de uma empresa depende do preço x, em reais, do produto que pode ser descrito pela função L(x) = -2x² + 16x - 20.\nQual deve ser o preço do produto para se obter o maior lucro possível?","alt":{"A":"2 reais","B":"4 reais","C":"6 reais","D":"8 reais"},"gabarito":"B","justificativa":"L(x) é uma parábola com concavidade para baixo (coeficiente de x² negativo), então o lucro máximo ocorre exatamente no vértice. A coordenada x do vértice é dada por x = −b/(2a) = −16/(2×(−2)) = −16/(−4) = 4. Portanto, o preço que maximiza o lucro é R$ 4, alternativa B.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Funções e equações do 2º grau"},"19":{"enunciado":"Kárita deseja construir um jardim retangular com área de 8 m². O comprimento do jardim deve ser 2 metros maior que a largura. Sendo x a largura do jardim, a equação que representa essa situação é:\nx (x + 2) = 8\nEntão os possíveis valores para x são:","alt":{"A":"1","B":"2","C":"3","D":"4"},"gabarito":"B","justificativa":"Desenvolvendo x(x+2) = 8, temos x² + 2x − 8 = 0. Fatorando: (x + 4)(x − 2) = 0, o que dá x = −4 ou x = 2. Como x representa uma medida de largura, precisa ser positivo, então x = 2 é a única solução válida — alternativa B.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Funções e equações do 2º grau"},"20":{"enunciado":"A seguir está representado o gráfico de uma função do 2º grau, que passa pelo ponto C=(0,8) no eixo y e possui raízes em B=(2,0) e A=(4,0).\nA lei de formação dessa função é:","alt":{"A":"f(x) = x² - 6x + 8","B":"f(x) = x² + 8x - 6","C":"f(x) = x² + 2x + 4","D":"f(x) = x² - 4x + 2"},"gabarito":"A","justificativa":"O gráfico mostra as raízes da função em x = 2 e x = 4, e o valor em x = 0 (ponto C) é 8. Testando a alternativa A: f(x) = x² − 6x + 8 = (x−2)(x−4) tem raízes exatamente em 2 e 4, e f(0) = 8, batendo com o ponto C do gráfico. Por isso a resposta é A. As outras alternativas não têm essas duas raízes simultaneamente.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Funções e equações do 2º grau"},"21":{"enunciado":"Na figura, um triângulo isósceles tem base 100 e os dois ângulos da base medindo 30° cada. Uma altura é traçada do vértice superior até a base, formando um ângulo reto. Calcule o valor de x, o segmento da base até o pé dessa altura.","alt":{"A":"50","B":"60","C":"100","D":"100√3/2"},"gabarito":"A","justificativa":"Como os dois ângulos da base medem 30°, o triângulo é isósceles, e a altura traçada do vértice do topo até a base é também mediana — ou seja, ela cai exatamente no ponto médio da base, dividindo-a em duas partes iguais. Como a base mede 100, cada metade mede 100 ÷ 2 = 50. Logo x = 50, alternativa A.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Geometria — triângulos e ângulos"},"22":{"enunciado":"Se o triângulo ABC da figura abaixo é equilátero de lado a, então a medida de QM em função de a e x é (figura com cevianas internas AP, PN, NM formando ângulos de 30° e ângulos retos em P e Q):","alt":{"A":"(3a-x)/4","B":"(3a-x)/8","C":"(8x+3a)/8","D":"(9x-3a)/8"},"gabarito":"D","justificativa":"Esta é uma questão de geometria mais avançada: o triângulo equilátero ABC é dividido por segmentos internos que formam ângulos de 30° com os lados, criando vários triângulos retângulos menores (com ângulos 30°-60°-90°). A estratégia é escrever cada segmento da base (AQ, QM, MB) em função de a e x usando as razões trigonométricas desses triângulos 30-60-90, e depois isolar QM a partir da soma AQ + QM + MB = AB = a (ou da relação equivalente ao longo do lado). Resolvendo esse sistema, chega-se a QM = (9x − 3a)/8, alternativa D. Por ser uma questão de várias etapas, vale resolver com calma no quadro com a turma, destacando cada triângulo 30-60-90 separadamente.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Geometria — triângulos e ângulos"},"23":{"enunciado":"Um círculo de área 16π está inscrito em um quadrado. O perímetro do quadrado é igual a:","alt":{"A":"32","B":"28","C":"24","D":"20"},"gabarito":"A","justificativa":"Área do círculo = πr² = 16π, logo r² = 16 e r = 4. O diâmetro do círculo é 2r = 8. Como o círculo está inscrito no quadrado (toca os quatro lados), o diâmetro do círculo é igual ao lado do quadrado: lado = 8. O perímetro do quadrado é 4 × lado = 4 × 8 = 32, alternativa A.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Geometria — áreas e perímetros"},"24":{"enunciado":"A área de um losango é 120 cm². Calcular o seu perímetro, sabendo que uma das diagonais vale 10 cm.","alt":{"A":"48 cm","B":"52 cm","C":"60 cm","D":"40 cm"},"gabarito":"B","justificativa":"A área do losango é (D × d)/2, onde D e d são as diagonais. Sabendo que uma diagonal é 10 e a área é 120: 120 = (10 × d)/2 → 120 = 5d → d = 24. As diagonais de um losango se cruzam formando ângulos retos e se bissectam, então cada lado é a hipotenusa de um triângulo retângulo com catetos igual à metade de cada diagonal: 10/2 = 5 e 24/2 = 12. Pelo teorema de Pitágoras, lado = √(5² + 12²) = √(25+144) = √169 = 13. O perímetro é 4 × 13 = 52 cm, alternativa B.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Geometria — áreas e perímetros"},"25":{"enunciado":"O valor do suplementar do ângulo α na figura abaixo (ângulos inscritos numa circunferência cortada por uma reta tangente t), sabendo-se que â = 90°, b̂ = 40° e ĉ = 15°, é:","alt":{"A":"160°","B":"168°","C":"155°","D":"135°"},"gabarito":"C","justificativa":"Esta questão usa o teorema do ângulo formado entre uma tangente e uma secante (ou entre duas secantes) a uma circunferência, que é igual à semidiferença dos arcos que ele determina. Aplicando esse teorema aos arcos indicados na figura (relacionados a â = 90° e b̂ = 40°), obtém-se α = (90° − 40°) / 2 = 25°. O ângulo suplementar de α é 180° − 25° = 155°, alternativa C. Vale reforçar com a turma o teorema específico (ângulo de segmento/tangente) usado nesse tipo de figura, já que é um conteúdo que costuma gerar dúvida.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Geometria — ângulos na circunferência"},"26":{"enunciado":"O valor da expressão [ (1/32)^(−2/5) · (2/3)^(−4) · (3)^(−3) ] / [ (5,3)^0 + (1/3)^(−1) ]^(−1) é igual a:","alt":{"A":"3","B":"4","C":"5","D":"6"},"gabarito":"A","justificativa":"Resolvendo por partes. No numerador: (1/32)^(−2/5) = 32^(2/5) = (2⁵)^(2/5) = 2² = 4; (2/3)^(−4) = (3/2)⁴ = 81/16; (3)^(−3) = 1/27. Multiplicando: 4 × 81/16 × 1/27 = 324/432 = 3/4. No denominador: (5,3)^0 = 1 (qualquer número elevado a 0 é 1); (1/3)^(−1) = 3; a soma é 1 + 3 = 4; elevando a −1: 4^(−1) = 1/4. Por fim, dividindo numerador pelo denominador: (3/4) ÷ (1/4) = 3. Alternativa A.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Álgebra — potenciação e radiciação"},"27":{"enunciado":"Se [ (4⁵+4⁵+4⁵+4⁵) / (3⁵+3⁵+3⁵) ] · [ (6⁵+6⁵+6⁵+6⁵+6⁵+6⁵) / (2⁵+2⁵) ] = 2ⁿ, onde n é um inteiro positivo, então n é igual a:","alt":{"A":"10","B":"12","C":"14","D":"16"},"gabarito":"B","justificativa":"Cada soma de parcelas iguais vira uma multiplicação: 4⁵+4⁵+4⁵+4⁵ = 4×4⁵ = 4⁶; 3⁵+3⁵+3⁵ = 3×3⁵ = 3⁶; 6⁵ somado 6 vezes = 6×6⁵ = 6⁶; 2⁵+2⁵ = 2×2⁵ = 2⁶. A expressão fica (4⁶/3⁶) × (6⁶/2⁶). Como 4=2² e 6=2×3, escrevemos tudo em potências de 2 e 3: 4⁶ = 2¹²; 6⁶ = 2⁶×3⁶. Substituindo: (2¹²/3⁶) × (2⁶×3⁶/2⁶) = (2¹²/3⁶) × 3⁶ = 2¹². Logo 2ⁿ = 2¹², e n = 12, alternativa B.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Álgebra — potenciação e radiciação"},"28":{"enunciado":"O valor do número √(11 + 6√2) + √(11 − 6√2) é igual a","alt":{"A":"7","B":"6","C":"√22","D":"3"},"gabarito":"B","justificativa":"Chamando a expressão de S e elevando ao quadrado: S² = (11+6√2) + (11−6√2) + 2√[(11+6√2)(11−6√2)]. Os termos com √2 se cancelam na soma: 11+11 = 22. No produto dentro da raiz, usa-se a diferença de quadrados: (11+6√2)(11−6√2) = 11² − (6√2)² = 121 − 72 = 49. Então S² = 22 + 2×√49 = 22 + 2×7 = 22+14 = 36. Como S é uma soma de raízes (positiva), S = √36 = 6, alternativa B.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Álgebra — potenciação e radiciação"},"29":{"enunciado":"Uma biblioteca possui 300 livros, todos do mesmo tamanho. Um funcionário pretende dividi-los igualmente entre as prateleiras da loja. Sabendo que, se os livros forem igualmente divididos entre 3 prateleiras a menos, cada prateleira receberá 5 livros a mais do que o previsto inicialmente.\nAssim, o número de prateleiras para colocar todos os livros é:","alt":{"A":"Múltiplo de 4.","B":"Múltiplo de 3.","C":"Entre 10 e 12.","D":"Maior que 20."},"gabarito":"B","justificativa":"Sendo n o número de prateleiras planejado inicialmente, cada uma recebe 300/n livros. Com 3 prateleiras a menos (n−3 prateleiras), cada uma passa a receber 300/(n−3), que é 5 livros a mais: 300/(n−3) = 300/n + 5. Multiplicando tudo por n(n−3) e simplificando, chega-se à equação do 2º grau n² − 3n − 180 = 0, cujas raízes são n = 15 ou n = −12 (descartada por ser negativa). Então o número de prateleiras planejado é 15, que é múltiplo de 3 (e também de 5) — alternativa B.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Álgebra — equações e sistemas"},"30":{"enunciado":"Paga-se um fogão de R$ 180,00 com cédulas de R$ 5,00 e de R$ 10,00. Se o número total de cédulas é 23, então necessariamente foi pago com:","alt":{"A":"10 cédulas de R$ 5,00","B":"12 cédulas de R$ 5,00","C":"13 cédulas de R$ 5,00","D":"14 cédulas de R$ 5,00"},"gabarito":"A","justificativa":"Chamando de x o número de cédulas de R$5 e y o de cédulas de R$10, temos duas equações: x + y = 23 (total de cédulas) e 5x + 10y = 180 (valor total pago). Isolando y na primeira equação (y = 23 − x) e substituindo na segunda: 5x + 10(23 − x) = 180 → 5x + 230 − 10x = 180 → −5x = −50 → x = 10. Conferindo: 10 cédulas de R$5 (R$50) + 13 cédulas de R$10 (R$130) = R$180 e 10+13=23 cédulas — tudo bate. Portanto, foram necessariamente 10 cédulas de R$5,00, alternativa A. <i>(Observação: o documento oficial do Percurso havia destacado a alternativa \"d\" por engano; o gabarito desta questão foi corrigido para \"a\" após conferência do cálculo.)</i>","passage":null,"passage_title":null,"aviso":false,"conteudo":"Álgebra — equações e sistemas"},"31":{"enunciado":"Os sacos aéreos são umas das importantes estruturas relacionadas com o voo das aves, pois deixam o corpo desses animais mais leve. Entre as alternativas abaixo, marque aquela que não pode ser considerada como uma adaptação ao voo.","alt":{"A":"ossos pneumáticos.","B":"quilha.","C":"ausência de dentes.","D":"glândula uropigiana."},"gabarito":"D","justificativa":"Ossos pneumáticos (A), quilha — a saliência do esterno onde se fixam os músculos do voo (B) — e ausência de dentes, que reduz o peso da cabeça (C), são adaptações diretamente ligadas a tornar a ave mais leve ou mais apta ao voo. Já a glândula uropigiana (D) produz uma secreção oleosa usada para impermeabilizar as penas — importante para a ave, mas não é uma adaptação que reduz peso ou está diretamente relacionada à mecânica do voo, o que a torna a alternativa correta (a que NÃO é adaptação ao voo).","passage":null,"passage_title":null,"aviso":false,"conteudo":"Zoologia — adaptações das aves"},"32":{"enunciado":"No desenvolvimento posterior à fecundação das angiospermas, união do núcleo espermático com a oosfera, o óvulo e o ovário originam, respectivamente,","alt":{"A":"fruto, semente e embrião.","B":"embrião, fruto e semente.","C":"embrião, semente e fruto.","D":"semente, fruto e embrião."},"gabarito":"C","justificativa":"Na dupla fecundação das angiospermas: a união do núcleo espermático com a oosfera origina o embrião; o óvulo (estrutura que envolve a oosfera) se transforma em semente após a fecundação; e o ovário (que envolve o óvulo) se transforma em fruto. Ou seja: núcleo espermático + oosfera → embrião; óvulo → semente; ovário → fruto — exatamente a ordem da alternativa C.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Botânica — reprodução das angiospermas"},"33":{"enunciado":"Compare NaCl e CO₂. O NaCl apresenta alto ponto de fusão e forma um sólido cristalino, enquanto o CO₂ é um gás à temperatura ambiente. A principal explicação para essa diferença é:","alt":{"A":"o NaCl possui ligação iônica e o CO₂ possui ligação covalente.","B":"ambos possuem ligações metálicas.","C":"o CO₂ é iônico e o NaCl é molecular.","D":"o NaCl possui ligação covalente e o CO₂ possui ligação iônica."},"gabarito":"A","justificativa":"O NaCl é um composto iônico: forma uma rede cristalina com fortes forças de atração entre os íons Na⁺ e Cl⁻, o que explica seu alto ponto de fusão e estado sólido. Já o CO₂ é uma molécula covalente, com forças intermoleculares fracas (Van der Waals), o que explica por que é gasoso à temperatura ambiente. Essa é exatamente a explicação da alternativa A. As outras alternativas invertem os tipos de ligação ou citam ligação metálica, que não se aplica a nenhum dos dois compostos.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Ligações químicas"},"34":{"enunciado":"Em uma residência, uma pessoa utiliza diferentes materiais para realizar tarefas do dia a dia. Ao cozinhar, percebe que uma panela de metal aquece rapidamente e, ao utilizar um fio metálico conectado a um circuito elétrico, observa que a corrente consegue passar por ele. Essas características estão relacionadas à estrutura das substâncias metálicas e ao tipo de interação existente entre seus átomos.\nCom base nessas propriedades, a boa condução de eletricidade e de calor apresentada pelos metais está relacionada principalmente:","alt":{"A":"à presença de moléculas polares em sua estrutura.","B":"à presença de elétrons livres na estrutura metálica.","C":"à formação de íons negativos entre os átomos.","D":"à ausência de elétrons na camada de valência."},"gabarito":"B","justificativa":"Os metais formam um retículo cristalino em que os elétrons da camada de valência ficam livres para se mover por toda a estrutura (o chamado \"mar de elétrons\"), formando a ligação metálica. São exatamente esses elétrons livres que permitem a boa condução de calor e eletricidade — resposta B. Os metais não formam moléculas polares (A), não se organizam por meio de íons negativos entre si (C), e não é a ausência de elétrons de valência que explica a condutividade, e sim sua mobilidade (D).","passage":null,"passage_title":null,"aviso":false,"conteudo":"Ligações químicas"},"35":{"enunciado":"O ferro reage com o enxofre para formar sulfeto de ferro (FeS), de acordo com a reação: Fe + S → FeS.\nEm um experimento, verificou-se que 28 g de ferro reagem completamente com 16 g de enxofre, formando sulfeto de ferro.\nConsiderando as Leis de Lavoisier e Proust, se forem utilizados 56g de ferro para realizar a reação completa, quais serão, respectivamente, as massas de enxofre necessárias e de sulfeto de ferro formadas?","alt":{"A":"16 g de enxofre e 44 g de sulfeto de ferro.","B":"32 g de enxofre e 88 g de sulfeto de ferro.","C":"28 g de enxofre e 84 g de sulfeto de ferro.","D":"32 g de enxofre e 84 g de sulfeto de ferro."},"gabarito":"B","justificativa":"Pela Lei de Proust, a proporção entre as massas dos reagentes é sempre constante: 28 g de ferro reagem com 16 g de enxofre. Usando 56 g de ferro (o dobro de 28 g), a massa de enxofre necessária também dobra: 16 × 2 = 32 g. Pela Lei de Lavoisier (conservação da massa), a massa do produto formado é a soma das massas dos reagentes: 56 + 32 = 88 g de FeS. Isso corresponde à alternativa B.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Estequiometria — leis ponderais"},"36":{"enunciado":"Uma bandeira possui faixas vermelha, verde e azul. Em uma determinada situação, ela é iluminada exclusivamente por uma luz monocromática verde. Ao observar a bandeira, as faixas vermelha, verde e azul serão vistas, respectivamente, como:","alt":{"A":"verde, verde e verde.","B":"preta, verde e preta.","C":"vermelha, branca e azul.","D":"preta, branca e verde."},"gabarito":"B","justificativa":"Um objeto colorido só reflete a cor da luz que incide sobre ele se essa for também \"a sua cor\"; caso contrário, absorve a luz e aparece preto (sem luz para refletir), pois não há outra cor de luz disponível na iluminação monocromática. Sob luz verde: a faixa verde reflete a luz verde e continua parecendo verde; as faixas vermelha e azul absorvem a luz verde (não é a cor que refletiriam) e, sem outra luz para refletir, aparecem pretas. Isso corresponde à alternativa B.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Óptica — propagação e cor da luz"},"37":{"enunciado":"Durante um eclipse solar, a Lua pode bloquear a luz do Sol e produzir uma região de sombra sobre a Terra. Esse fenômeno está relacionado principalmente ao princípio de que:","alt":{"A":"A luz sempre se propaga em curvas.","B":"A luz se propaga em linha reta em meios homogêneos e transparentes.","C":"A luz não pode atravessar o espaço.","D":"A luz sempre muda de direção ao se propagar."},"gabarito":"B","justificativa":"A formação de sombra (como no eclipse) só é possível porque a luz se propaga em linha reta em meios homogêneos — é esse princípio da óptica geométrica que explica por que um obstáculo opaco (a Lua) bloqueia a luz e cria uma região de sombra bem definida atrás de si, em vez de a luz \"contornar\" o obstáculo. Isso corresponde à alternativa B. As demais alternativas contradizem princípios básicos da propagação da luz.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Óptica — propagação e cor da luz"},"38":{"enunciado":"Durante um dia frio, uma pessoa coloca uma panela com água sobre a chama do fogão. Depois de alguns minutos, percebe que:\n- o cabo metálico da panela fica quente;\n- a água no interior da panela começa a circular, com a água quente subindo e a fria descendo;\n- mesmo estando próxima ao fogão, ela sente o calor da chama sem encostar nela.\nEssas três situações correspondem, respectivamente, a:","alt":{"A":"Convecção, condução e irradiação.","B":"Condução, convecção e irradiação.","C":"Irradiação, condução e convecção.","D":"Condução, irradiação e convecção."},"gabarito":"B","justificativa":"O calor se propaga de três formas: condução (transmissão de calor de partícula a partícula em um sólido, sem transporte de matéria — o cabo da panela esquentando), convecção (movimento de um fluido, como a água circulando entre as regiões quente e fria) e irradiação (propagação de calor por ondas eletromagnéticas, mesmo sem contato — sentir o calor do fogo à distância). Na ordem em que os eventos aparecem no enunciado (cabo esquenta → água circula → calor sentido à distância), temos condução, convecção e irradiação — alternativa B.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Termologia — transmissão de calor"},"39":{"enunciado":"A gentrificação é um processo urbano caracterizado pela:","alt":{"A":"Expansão das áreas rurais dentro das cidades, com redução da população urbana.","B":"Valorização de determinadas áreas urbanas, podendo provocar a saída de moradores de menor renda devido ao aumento do custo de vida.","C":"Construção de moradias populares em áreas centrais, reduzindo o preço dos imóveis.","D":"Diminuição dos investimentos privados em regiões urbanas consideradas degradadas."},"gabarito":"B","justificativa":"Gentrificação é o processo em que um bairro (geralmente antes popular ou degradado) passa por reformas e valorização imobiliária, atraindo moradores de maior poder aquisitivo e investimentos. Com isso, o custo de vida na região sobe e os moradores originais, de menor renda, muitas vezes não conseguem mais arcar com os custos e acabam se mudando. Essa é exatamente a descrição da alternativa B. As demais alternativas descrevem o oposto do fenômeno (expansão rural, moradias populares baratas, desinvestimento).","passage":null,"passage_title":null,"aviso":false,"conteudo":"Geografia urbana (gentrificação e conurbação)"},"40":{"enunciado":"Os movimentos tectônicos podem ser classificados, entre outros, em orogênese e epirogênese. Sobre esses processos, assinale a alternativa correta:","alt":{"A":"A orogênese ocorre principalmente por movimentos verticais.","B":"A epirogênese provoca principalmente dobramentos e cordilheiras.","C":"A orogênese pode provocar dobramentos e falhamentos, formando montanhas.","D":"A epirogênese ocorre somente no encontro entre placas tectônicas."},"gabarito":"C","justificativa":"A orogênese é o processo de formação de cadeias de montanhas, geralmente por movimentos horizontais (compressão) das placas tectônicas, que provocam dobramentos e falhamentos — o que torna a alternativa C correta. A epirogênese, por sua vez, envolve movimentos verticais mais lentos e suaves (soerguimento ou rebaixamento de grandes áreas), sem formar cadeias de montanhas — o oposto do que dizem as alternativas A e B. A epirogênese também não ocorre \"somente\" no encontro de placas (D), podendo acontecer em áreas mais estáveis da crosta.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Geomorfologia — tectônica"},"41":{"enunciado":"Com o crescimento das cidades, áreas urbanizadas de municípios próximos podem se expandir até se unirem, formando uma única área urbana contínua. Esse processo é chamado de conurbação. Assinale a alternativa correta:","alt":{"A":"União física das áreas urbanizadas de cidades próximas.","B":"Separação entre áreas urbanas e rurais.","C":"Redução da população das grandes cidades.","D":"Crescimento de cidades sem contato com outros municípios."},"gabarito":"A","justificativa":"O próprio enunciado já define conurbação: cidades vizinhas que crescem até suas áreas urbanas se encontrarem e formarem um tecido urbano contínuo. A alternativa A apenas reafirma essa definição corretamente. As demais alternativas descrevem processos opostos ou não relacionados (separação, redução populacional, crescimento isolado).","passage":null,"passage_title":null,"aviso":false,"conteudo":"Geografia urbana (gentrificação e conurbação)"},"42":{"enunciado":"A transição demográfica é um processo relacionado às mudanças nas taxas de natalidade e mortalidade de uma população. Sobre esse processo, assinale a alternativa correta:","alt":{"A":"Caracteriza-se pelo aumento contínuo das taxas de natalidade e mortalidade.","B":"Ocorre quando a população deixa de apresentar qualquer crescimento demográfico.","C":"Está relacionada à redução das taxas de mortalidade e, posteriormente, das taxas de natalidade, acompanhando mudanças sociais e econômicas.","D":"Ocorre exclusivamente em países desenvolvidos e não pode ser observada em países em desenvolvimento."},"gabarito":"C","justificativa":"A transição demográfica descreve a passagem de um regime de altas taxas de natalidade e mortalidade para um regime de taxas baixas: primeiro a mortalidade cai (com avanços da saúde e saneamento) e, só depois, com uma defasagem, a natalidade também cai (por urbanização, acesso a educação e planejamento familiar). É exatamente o que descreve a alternativa C. As demais alternativas contradizem esse processo ou o limitam de forma incorreta, já que a transição demográfica ocorre também em países em desenvolvimento, apenas em ritmos e momentos diferentes.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Demografia — transição demográfica"},"43":{"enunciado":"Sobre as correntes marítimas, assinale a alternativa correta:","alt":{"A":"Correntes frias favorecem a aridez costeira.","B":"Correntes quentes reduzem a evaporação.","C":"Correntes frias elevam a umidade costeira.","D":"Correntes quentes impedem a formação de chuvas."},"gabarito":"A","justificativa":"Correntes marítimas frias resfriam o ar acima delas, dificultando a evaporação e a formação de nuvens de chuva na costa — por isso, regiões costeiras banhadas por correntes frias tendem a ser mais áridas (como o deserto do Atacama, no Chile). Isso confirma a alternativa A. Já as correntes quentes fazem o oposto: aumentam a evaporação e favorecem a formação de chuvas, o que torna as alternativas B, C e D incorretas (a C erra ao atribuir aumento de umidade à corrente fria, e B e D invertem o efeito das correntes quentes).","passage":null,"passage_title":null,"aviso":false,"conteudo":"Climatologia — correntes marítimas"},"44":{"enunciado":"Sobre os conceitos fundamentais da Geografia, assinale a alternativa correta:","alt":{"A":"Território envolve relações de poder e apropriação do espaço.","B":"Lugar corresponde a qualquer espaço delimitado politicamente.","C":"Paisagem é formada apenas por elementos naturais perceptíveis.","D":"Região apresenta necessariamente características homogêneas."},"gabarito":"A","justificativa":"Na Geografia, \"território\" é definido justamente pela ideia de poder e controle sobre um espaço (seja de um Estado, grupo social ou indivíduo) — o que torna a alternativa A correta. \"Lugar\" está ligado à experiência e identidade das pessoas com o espaço, não apenas a limites políticos (B incorreta). \"Paisagem\" inclui tanto elementos naturais quanto humanos/construídos, não somente os naturais (C incorreta). E \"região\" pode ser definida por critérios diversos, nem sempre exigindo homogeneidade total — existem regiões funcionais, por exemplo, definidas pela interligação entre lugares diferentes entre si (D incorreta).","passage":null,"passage_title":null,"aviso":false,"conteudo":"Conceitos fundamentais da Geografia"},"45":{"enunciado":"Sobre o início do governo provisório de Getúlio Vargas (1930-1934), pode-se afirmar que:","alt":{"A":"Getúlio Vargas chegou ao poder por vencer as eleições diretas em 1929 com o seu vice, o paraibano João Pessoa.","B":"iniciou-se com um levante em vários estados do Brasil, que culminou com a deposição do presidente Washington Luiz.","C":"teve início com a proclamação da República em 1989, quando Getúlio juntamente com militares retirou D. Pedro II do poder.","D":"com a Revolta dos Tenentes, que ficou conhecida como Tenentismo, uma junta militar tomou o poder do presidente Washington Luiz."},"gabarito":"B","justificativa":"Getúlio Vargas chegou ao poder pela Revolução de 1930, um levante armado que começou no Rio Grande do Sul e se espalhou por vários estados, resultando na deposição do presidente Washington Luís e impedindo a posse do candidato eleito Júlio Prestes — o que corresponde à alternativa B. A alternativa A está errada porque Vargas não venceu as eleições de 1929 (ele perdeu; chegou ao poder pela via revolucionária). A C mistura datas e fatos incompatíveis (a Proclamação da República foi em 1889, derrubando D. Pedro II, não Vargas). A D confunde o Tenentismo (movimento de tenentes das décadas anteriores) com o episódio de 1930, que não foi conduzido por uma junta militar tenentista.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Ascensão de Vargas (Revolução de 1930)"},"46":{"enunciado":"Uma das grandes mudanças trazidas pelo Governo Vargas foi o Código Eleitoral de 1932, que trouxe várias mudanças positivas para o processo das eleições brasileiras. Assinale a alternativa abaixo que não corresponde a um desses avanços.","alt":{"A":"A fiscalização das eleições, que antes eram acompanhadas pelo poder legislativo, passou a ser de responsabilidade de órgãos ligados ao poder judiciário.","B":"Foi instituído o voto secreto nas eleições, com o intuito de dificultar as fraudes e as pressões de políticos no intuito de influenciar o voto de outros eleitores.","C":"As eleições passaram a ocorrer a cada dois anos, com a possibilidade de se ampliar por mais três anos sem novas eleições.","D":"Estendeu o direito às mulheres a votar nas eleições, permitindo que elas também participassem da escolha de seus representantes."},"gabarito":"C","justificativa":"O Código Eleitoral de 1932 trouxe avanços reais como a criação da Justiça Eleitoral (fiscalização por órgãos do Judiciário, alternativa A), o voto secreto (B) e o voto feminino (D) — todos avanços democráticos verdadeiros. Já a alternativa C descreve algo que não corresponde a um avanço real do código: não houve essa previsão de eleições a cada dois anos com prorrogação de até três anos sem novas eleições — o que, inclusive, seria um retrocesso (adiar eleições), e não um avanço. Por isso C é a alternativa correta a ser assinalada (a que NÃO corresponde a um avanço).","passage":null,"passage_title":null,"aviso":false,"conteudo":"Reformas democráticas (Código Eleitoral)"},"47":{"enunciado":"Durante a campanha eleitoral de 1937, quando havia a real possibilidade de Getúlio Vargas deixar o poder, o presidente em exercício e seus aliados divulgaram na imprensa que haveria mais uma conspiração comunista para tomar o Brasil, plano esse que nunca foi confirmado e há indícios que teria sido forjado para garantir o poder para Vargas, o chamado Estado Novo, a Ditadura Varguista. Esse suposto plano ficou conhecido como","alt":{"A":"plano Cohen.","B":"plano Vargas.","C":"plano Coreia.","D":"plano de Ação."},"gabarito":"A","justificativa":"O episódio é conhecido na história do Brasil como \"Plano Cohen\": um documento forjado (atribuído a um suposto plano comunista) usado como justificativa para o golpe que instaurou o Estado Novo em 1937. É um nome consagrado nos livros de história — alternativa A. As demais opções são nomes que não correspondem a esse evento histórico específico.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Estado Novo e autoritarismo"},"48":{"enunciado":"Apesar de governar por oito anos como ditador, Getúlio Vargas entrou para a história como \"Pai dos Pobres\", principalmente devido aos avanços nas leis trabalhistas que ocorreram durante o seu governo. A CLT (Consolidação das Leis do Trabalho) foi um marco para a história do Brasil e garantiu muito apoio para ele.\nAssinale abaixo o único item que não corresponde a um direito trabalhista criado pelo governo de Getúlio.","alt":{"A":"Férias anuais remuneradas.","B":"Jornada de trabalho de 8 horas diárias.","C":"Criação do salário mínimo.","D":"Décimo Terceiro Salário."},"gabarito":"D","justificativa":"Férias remuneradas (A), jornada de 8 horas (B) e salário mínimo (C) foram todos direitos efetivamente instituídos durante o governo Vargas, consolidados na CLT (1943). Já o décimo terceiro salário (D) só foi criado décadas depois, em 1962, no governo João Goulart — não fazendo parte do pacote trabalhista da era Vargas. Por isso D é a alternativa correta a ser assinalada (a que NÃO corresponde a um direito criado por Getúlio).","passage":null,"passage_title":null,"aviso":false,"conteudo":"Legislação trabalhista (CLT)"},"49":{"enunciado":"Em 1939, durante o Estado Novo, foi criado o Departamento de Imprensa e Propaganda (DIP), que tinha como principal objetivo promover a imagem do governo através de propagandas que trouxessem a ideia de união e desenvolvimento da nação sob o comando de Getúlio Vargas. Assinale a alternativa que corresponde a uma das ações do DIP que continua a existir até os dias atuais:","alt":{"A":"Criação de cartilhas educativas que exaltavam o governo nas escolas.","B":"Produção de filmes, que exaltavam o nacionalismo e a ideologia do trabalhismo.","C":"Censura e controle dos meios de comunicação.","D":"Produção e veiculação do programa de rádio a Voz do Brasil."},"gabarito":"D","justificativa":"Entre as ações do DIP, a \"Hora do Brasil\" (hoje \"A Voz do Brasil\") é a única que continua existindo até hoje, transmitida diariamente pelas emissoras de rádio brasileiras, embora com formato e conteúdo bem diferentes dos da época de Vargas. As cartilhas escolares, os filmes de propaganda e a censura direta da época do DIP não são práticas que continuam institucionalizadas da mesma forma atualmente — o que torna D a alternativa correta.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Estado Novo e autoritarismo"},"50":{"enunciado":"Sobre o Queremismo, movimento que eclodiu no Brasil em 1945, é correto afirmar que era:","alt":{"A":"Um movimento de caráter militar que exigia o fim imediato e a punição de Getúlio Vargas.","B":"Um movimento das elites políticas oligárquicas em oposição à criação do PTB.","C":"Um movimento nacionalista de neutralidade na Segunda Guerra Mundial.","D":"Um movimento popular e trabalhista que defendia a permanência de Getúlio Vargas na presidência."},"gabarito":"D","justificativa":"O nome \"Queremismo\" vem do slogan \"Queremos Getúlio\", um movimento popular (com apoio de trabalhistas e comunistas) que defendia a permanência de Vargas no poder e a convocação de uma Assembleia Constituinte com ele à frente, em 1945 — o que corresponde exatamente à alternativa D. As demais alternativas descrevem o oposto (movimento contra Vargas) ou temas não relacionados ao Queremismo.","passage":null,"passage_title":null,"aviso":false,"conteudo":"Queremismo"}};
const DEFAULT_TOPIC_TOTALS = {"Interpretação":5,"Gramática":10,"Aritmética":5,"Álgebra e Geometria":10,"Biologia":2,"Química":3,"Física":3,"Geografia":6,"História":6};
/* =====================================================================================
   OMR — leitura óptica dos cartões-resposta (rodadas CEFET)
   =====================================================================================
   Calibração do grid de bolhas, derivada de um cartão de referência real (aluno Gabriel
   de Oliveira Leitão, simulado Pré-CEFET 2026) renderizado a 300dpi e analisado com
   OpenCV (findContours para achar o retângulo externo do cartão + HoughCircles para
   achar ~50 das 200 bolhas, agrupadas em 12 colunas de X e 17 linhas de Y por gap
   detection). O crop de referência (já recortado exatamente na borda do cartão) tinha
   1515×2295px; as frações abaixo são posição-do-centro-da-bolha / (largura,altura) desse
   crop — ou seja, são relativas aos 4 cantos da borda do cartão, 0..1 em cada eixo,
   independente da resolução real do scan do usuário. A checagem visual (círculos
   desenhados nessas posições sobre o crop original) bateu nas 200 bolhas.
   Layout: 3 colunas impressas — coluna 1 = questões 1–17, coluna 2 = questões 18–34,
   coluna 3 = questões 35–50 (16 linhas só, mesmas 16 primeiras linhas de Y das outras
   duas colunas — a coluna 3 não tem a 17ª linha). Cada coluna tem 4 bolhas (A,B,C,D). */
const OMR_X_COLS = [
  [0.19967, 0.24475, 0.28759, 0.32944], // coluna 1 (Q1-17): A,B,C,D
  [0.44211, 0.48132, 0.52092, 0.56224], // coluna 2 (Q18-34): A,B,C,D
  [0.68647, 0.72866, 0.76667, 0.81003], // coluna 3 (Q35-50): A,B,C,D
];
const OMR_Y_ROWS = [ // 17 linhas (a coluna 3 usa só as 16 primeiras)
  0.47506, 0.50567, 0.53595, 0.56523, 0.59673, 0.62923, 0.65850, 0.68901,
  0.71852, 0.75122, 0.78213, 0.81340, 0.84575, 0.87755, 0.90772, 0.93712, 0.96585,
];
// raio de amostragem de cada bolha, em fração da largura do retângulo canônico do cartão
const OMR_BUBBLE_RADIUS_FRAC = 0.0125;
const OMR_LETTERS = ['A', 'B', 'C', 'D'];
// dimensões (em "pixels" arbitrários) do retângulo canônico usado como destino da
// homografia — só precisa manter proporção parecida com o cartão real; as frações acima
// é que carregam a posição de verdade.
const OMR_CANVAS_CW = 1000;
const OMR_CANVAS_CH = 1515;

function omrQuestionColRow(q) {
  if (q >= 1 && q <= 17) return { col: 0, row: q - 1 };
  if (q >= 18 && q <= 34) return { col: 1, row: q - 18 };
  if (q >= 35 && q <= 50) return { col: 2, row: q - 35 };
  throw new Error('questão fora do intervalo 1-50: ' + q);
}

/* Posição fracionária (0..1 relativo aos 4 cantos do cartão) de cada uma das 4 bolhas
   da questão q. Retorna { A:[x,y], B:[x,y], C:[x,y], D:[x,y] }. */
function omrBubblePositions(q) {
  const { col, row } = omrQuestionColRow(q);
  const y = OMR_Y_ROWS[row];
  const xs = OMR_X_COLS[col];
  const out = {};
  OMR_LETTERS.forEach((letra, i) => { out[letra] = [xs[i], y]; });
  return out;
}

const TOPIC_RANGES = [["Interpretação",1,5],["Gramática",6,15],["Aritmética",16,20],["Álgebra e Geometria",21,30],["Biologia",31,32],["Química",33,35],["Física",36,38],["Geografia",39,44],["História",45,50]];
const DEFAULT_TOPIC_ORDER = Object.keys(DEFAULT_TOPIC_TOTALS);
/* Estes dois começam apontando para o "padrão" (questão a questão, 9 grupos) mas são
   trocados por renderSimuladoAll() para o recorte por matéria quando a rodada carregada
   é do tipo "por_materia" (sem correção questão a questão). Tudo que monta o gráfico de
   tópicos / resumo do aluno / tags de pontos fracos usa estas duas variáveis, então passa
   a refletir automaticamente as matérias certas para cada rodada. */
let TOPIC_TOTALS = DEFAULT_TOPIC_TOTALS;
let TOPIC_ORDER = DEFAULT_TOPIC_ORDER;
const HORARIO = {A:"14:00 - 15:00", B:"15:00 - 16:00"};
function topicOf(q){ return TOPIC_RANGES.find(([t,a,b])=>q>=a&&q<=b)[0]; }
function isPorMateria(){ return !!(currentSimuladoMeta && currentSimuladoMeta.topico_ranges && currentSimuladoMeta.topico_ranges.tipo === 'por_materia'); }
function setTopicMetaForRound(meta){
  if (meta && meta.topico_ranges && meta.topico_ranges.tipo === 'por_materia' && Array.isArray(meta.topico_ranges.materias)) {
    const totals = {};
    meta.topico_ranges.materias.forEach(([nome, total]) => { totals[nome] = total; });
    TOPIC_TOTALS = totals;
    TOPIC_ORDER = meta.topico_ranges.materias.map(([nome]) => nome);
  } else {
    TOPIC_TOTALS = DEFAULT_TOPIC_TOTALS;
    TOPIC_ORDER = DEFAULT_TOPIC_ORDER;
  }
}


function avg(arr){return arr.reduce((a,b)=>a+b,0)/arr.length;}
function fmt1(n){return (Math.round(n*10)/10).toString().replace('.',',');}
function byName(nome){return STUDENTS.find(s=>s.nome===nome);}

/* Aluno do cadastro pelo nome. Antes era students.find(... normName ...) em cada linha das listas
   (~96 ms por redesenho no teste com 330 linhas); agora é um índice (Map) montado uma vez e refeito
   só quando a lista de alunos muda. */
let _alunosPorNome = null, _alunosPorNomeRef = null, _alunosPorNomeLen = -1;
function alunoPorNome(nome){
  if (_alunosPorNome === null || _alunosPorNomeRef !== students || _alunosPorNomeLen !== students.length) {
    _alunosPorNome = new Map();
    students.forEach(s => { const k = normName(s.nome); if (!_alunosPorNome.has(k)) _alunosPorNome.set(k, s); });
    _alunosPorNomeRef = students; _alunosPorNomeLen = students.length;
  }
  return _alunosPorNome.get(normName(nome)) || null;
}

/* Foto do aluno nas telas de Simulados: o avatar só recebe a foto (a miniatura, quando existe)
   quando aparece na tela — ver observarAvatares(). */
function simAvatarHTML(nome, size){
  size = size || 30;
  const cad = alunoPorNome(nome);
  const style = `width:${size}px;height:${size}px;font-size:${Math.max(10, Math.round(size*0.38))}px;background:${colorFor(nome)}`;
  let foto = '';
  if (cad && cad.fotoUrl) { foto = ` data-foto-aluno="${esc(cad.id)}" data-foto-orig="${esc(cad.fotoUrl)}"`; agendarScanFotos(); }
  return `<span class="sim-avatar" style="${style}"${foto}>${esc(initials(nome))}</span>`;
}

/* ---------------- VIEW ROUTER ---------------- */

function showView(name){
  ['homeView','studentView','correcaoView','professoresView'].forEach(id=>{
    const el = byId(id);
    const show = id === name;
    el.classList.toggle('hidden', !show);
    // define o display diretamente (estilo inline) para garantir que a troca de aba
    // funcione mesmo se alguma regra de CSS mudar no futuro — evita as abas ficarem
    // empilhadas umas sobre as outras.
    el.style.display = show ? '' : 'none';
  });
  document.querySelectorAll('#view-simulados [data-sim-tab]').forEach(b=>{
    b.classList.toggle('active', (name==='homeView' && b.dataset.simTab==='home') ||
                                  (name==='correcaoView' && b.dataset.simTab==='correcao') ||
                                  (name==='professoresView' && b.dataset.simTab==='professores'));
  });
  flushSimLazy(name);
}

/* ---------------- HOME: turma scope (rótulos e estado) ---------------- */

/* `simulado_resultados.turma_id` referencia turmas.id de verdade (a mesma tabela usada
   em Alunos/Financeiro/Horários), então os rótulos aqui vêm de turmasList — já filtrada
   pelo ano letivo selecionado — em vez de nomes genéricos fixos tipo "Turma 1"/"Turma 2". */
function turmaLabel(turmaId){ return turmaId ? nomeDaTurma(turmaId) : 'Sem turma definida'; }
function turmaShort(turmaId){
  const idx = turmasList.findIndex(t => t.id === turmaId);
  return idx === -1 ? '—' : 'T' + (idx + 1);
}
function turmaBadgeClass(turmaId){
  const idx = turmasList.findIndex(t => t.id === turmaId);
  return idx === -1 ? '' : 't' + ((idx % 2) + 1);
}

let state = {turma:'all', q:'', sortDesc:true};

function renderSimScopeCurrent(){
  const current = byId('simScopeCurrent');
  if (!current) return;
  const roundName = currentSimuladoMeta ? esc(currentSimuladoMeta.nome) : '—';
  current.innerHTML = `<b>${roundName}</b> · ${state.turma==='all' ? 'todas as turmas' : esc(turmaLabel(state.turma))}`;
}

/* ---------------- HOME: KPIs ---------------- */

function renderSimKpis(){
  if(STUDENTS.length===0){
    byId('kpis').innerHTML = '';
    return;
  }
  const totalMatriculados = state.turma==='all' ? STUDENTS.length : STUDENTS.filter(s=>s.turma===state.turma).length;
  let html = `<div class="kpi"><div class="lbl">Alunos avaliados</div><div class="val">${scopedPresentes.length}</div><div class="sub">${totalMatriculados} matriculados no total</div></div>`;
  if (state.turma==='all') {
    html += `<div class="kpi t1"><div class="lbl">Média ${esc(turmaLabel(CEFET_T1_ID))}</div><div class="val">${t1.length?fmt1(avg(t1.map(s=>s.acertos))):'—'}<span style="font-size:15px;color:var(--sim-muted);font-family:var(--sim-sans)"> /50</span></div><div class="sub">${t1.length} presentes</div></div>`;
    html += `<div class="kpi t2"><div class="lbl">Média ${esc(turmaLabel(CEFET_T2_ID))}</div><div class="val">${t2.length?fmt1(avg(t2.map(s=>s.acertos))):'—'}<span style="font-size:15px;color:var(--sim-muted);font-family:var(--sim-sans)"> /50</span></div><div class="sub">${t2.length} presentes</div></div>`;
  } else {
    html += `<div class="kpi ${turmaBadgeClass(state.turma)}"><div class="lbl">Média ${esc(turmaLabel(state.turma))}</div><div class="val">${scopedPresentes.length?fmt1(avg(scopedPresentes.map(s=>s.acertos))):'—'}<span style="font-size:15px;color:var(--sim-muted);font-family:var(--sim-sans)"> /50</span></div><div class="sub">${scopedPresentes.length} presentes</div></div>`;
  }
  html += `<div class="kpi falt"><div class="lbl">Faltosos</div><div class="val" style="color:var(--sim-danger)">${scopedFaltosos.length}</div><div class="sub">${scopedFaltosos.filter(s=>s.turma===CEFET_T1_ID).length} da ${esc(turmaShort(CEFET_T1_ID))} · ${scopedFaltosos.filter(s=>s.turma===CEFET_T2_ID).length} da ${esc(turmaShort(CEFET_T2_ID))}</div></div>`;
  byId('kpis').innerHTML = html;
}

function topicBarsHTML(topic, p1, p2){
  const total = TOPIC_TOTALS[topic];
  return `<div class="topic-row">
    <div class="topic-name">${topic}<br><span style="color:var(--sim-muted);font-size:11px">(${total} questões)</span></div>
    <div class="topic-bars">
      <div class="bar-track"><div class="bar-fill t1" style="width:${p1}%"><span class="bar-fill-label">${Math.round(p1)}%</span></div></div>
      <div class="bar-track"><div class="bar-fill t2" style="width:${p2}%"><span class="bar-fill-label">${Math.round(p2)}%</span></div></div>
    </div>
  </div>`;
}

function topicBarSingleHTML(topic, p, cls){
  const total = TOPIC_TOTALS[topic];
  return `<div class="topic-row">
    <div class="topic-name">${topic}<br><span style="color:var(--sim-muted);font-size:11px">(${total} questões)</span></div>
    <div class="topic-bars">
      <div class="bar-track"><div class="bar-fill ${cls}" style="width:${p}%"><span class="bar-fill-label">${Math.round(p)}%</span></div></div>
    </div>
  </div>`;
}

function renderSimTopicChart(){
  const el = byId('topicChart');
  const legend = el.previousElementSibling;
  if (state.turma==='all') {
    if (legend && legend.classList.contains('legend')) legend.style.display = '';
    el.innerHTML = TOPIC_ORDER.map(topic=>{
      const total = TOPIC_TOTALS[topic];
      const p1 = t1.length ? avg(t1.map(s=>s.topicos[topic]))/total*100 : 0;
      const p2 = t2.length ? avg(t2.map(s=>s.topicos[topic]))/total*100 : 0;
      return topicBarsHTML(topic,p1,p2);
    }).join('');
  } else {
    if (legend && legend.classList.contains('legend')) legend.style.display = 'none';
    const grupo = scopedPresentes;
    const cls = turmaBadgeClass(state.turma);
    el.innerHTML = TOPIC_ORDER.map(topic=>{
      const total = TOPIC_TOTALS[topic];
      const p = grupo.length ? avg(grupo.map(s=>s.topicos[topic]))/total*100 : 0;
      return topicBarSingleHTML(topic,p,cls);
    }).join('');
  }
}

/* ---------------- HOME: hardest questions chart ---------------- */

function renderQErrChart(){
  const el = byId('qerrChart');
  if (isPorMateria()) {
    el.innerHTML = `<div class="npbig"><div class="big">Sem correção questão a questão</div>Este simulado não teve correção por questão registrada — apenas notas por matéria estão disponíveis.</div>`;
    return;
  }
  const items = [];
  for(let q=1;q<=50;q++){
    const s = QSTATS[q];
    items.push({q, errPct: 100 - s.correct_pct, topic: topicOf(q)});
  }
  items.sort((a,b)=>b.errPct-a.errPct);
  const top = items.slice(0,15);
  const scopeNote = state.turma==='all' ? '' : ` · ${esc(turmaLabel(state.turma))}`;
  el.innerHTML = `<div class="legend">Mostrando as 15 questões com maior índice de erro (de 50)${scopeNote}</div>` +
    top.map(it=>`<div class="qerr-row" data-q="${it.q}">
      <div class="qerr-q">Q${it.q}</div>
      <div>
        <div style="font-size:12px;color:var(--sim-muted);margin-bottom:2px">${it.topic}</div>
        <div class="qerr-track"><div class="qerr-fill" style="width:${it.errPct}%"></div></div>
      </div>
      <div class="qerr-pct">${fmt1(it.errPct)}%</div>
    </div>`).join('');
  el.querySelectorAll('.qerr-row').forEach(row=>{
    row.addEventListener('click', ()=>{
      showView('correcaoView');
      openQuestion(parseInt(row.getAttribute('data-q')));
    });
  });
}

