function generateTips(topic, ctx){
  const {pAll, p1, p2, weakStudents, withTopic, worstQs} = ctx;
  const tips = [];
  const total = DEFAULT_TOPIC_TOTALS[topic];

  if(pAll < 50){
    tips.push(`A média geral neste conteúdo está abaixo de 50% (${fmt1(pAll)}%). Vale considerar uma aula de retomada dos fundamentos antes de avançar para exercícios mais complexos, em vez de seguir direto para revisão pontual.`);
  } else if(pAll < 75){
    tips.push(`A média geral (${fmt1(pAll)}%) mostra que a base existe, mas ainda com lacunas. Uma revisão direcionada nos pontos específicos abaixo (em vez de retomar tudo do zero) tende a ser mais eficiente.`);
  } else {
    tips.push(`A média geral está alta (${fmt1(pAll)}%) — a turma domina bem esse conteúdo. Pode ser um bom momento para propor exercícios de nível mais desafiador ou aprofundar aplicações, em vez de repetir revisão básica.`);
  }

  const gap = Math.abs(p1-p2);
  if(gap >= 12){
    const melhor = p1>p2 ? turmaLabel(CEFET_T1_ID) : turmaLabel(CEFET_T2_ID);
    const pior = p1>p2 ? turmaLabel(CEFET_T2_ID) : turmaLabel(CEFET_T1_ID);
    tips.push(`Há uma diferença grande entre as turmas (${fmt1(gap)} pontos percentuais, ${melhor} à frente). Vale considerar um ritmo ou abordagem diferente para a ${pior}, em vez de tratar as duas turmas da mesma forma neste conteúdo.`);
  }

  if(worstQs.length){
    const q = worstQs[0]; const s = QSTATS[q]; const c = QCONTENT[q];
    tips.push(`A Questão ${q} concentrou o maior número de erros (${fmt1(100-s.correct_pct)}%), e a maioria que errou marcou a alternativa ${s.most_wrong_letter}. Vale mostrar esse erro específico em sala — comparar a lógica de quem escolheu ${s.most_wrong_letter} com o raciocínio correto costuma corrigir o mal-entendido de forma mais duradoura do que só repetir a explicação.`);
  }

  const zeroCount = withTopic.filter(s=>s.topicos[topic]===0).length;
  if(zeroCount > 0 && total <= 5){
    tips.push(`${zeroCount} aluno(s) não acertou(aram) nenhuma questão deste conteúdo (que tem só ${total} questões no total). Como a amostra é pequena, vale conversar individualmente com esses alunos antes de tirar conclusões — pode ser lacuna de conteúdo, mas também pode ser tempo de prova ou atenção naquele bloco específico.`);
  }

  if(weakStudents.length / withTopic.length > 0.4){
    tips.push(`Mais de 40% da turma está abaixo de 50% neste conteúdo (${weakStudents.length} de ${withTopic.length}). Isso sugere um problema de turma, não só individual — pode valer a pena revisar com todo mundo antes de focar em casos pontuais.`);
  } else if(weakStudents.length > 0){
    tips.push(`O grupo abaixo de 50% é relativamente pequeno (${weakStudents.length} de ${withTopic.length}). Um atendimento em grupo pequeno ou nos horários de monitoria pode resolver sem precisar tomar tempo da aula toda.`);
  }

  tips.push(`Use o filtro "quantidade de acertos" na dashboard pra agrupar os alunos por faixa de domínio e montar atividades diferentes por grupo, em vez de uma aula única pra turma inteira.`);

  return tips;
}

function generateReportPdf(topic, teacher){
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({unit:'mm', format:'a4'});
  const PW = 210, PH = 297, MX = 16;
  let y = 20;
  const brand = [6,102,74], brandDark=[4,67,47], ink=[22,36,25], muted=[93,107,97], danger=[178,58,46];

  function checkPage(need){
    if(y + need > PH - 18){ doc.addPage(); addFooter(); y = 20; }
  }
  function addFooter(){
    const p = doc.internal.getNumberOfPages();
    doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(...muted);
    doc.text(`Percurso Cataguases — Relatório de Desempenho — página ${p}`, MX, PH-10);
  }

  // Header
  doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(...muted);
  doc.text('PERCURSO CATAGUASES — PRÉ-VESTIBULARES & CONCURSOS', MX, y); y+=8;
  doc.setDrawColor(...brand); doc.setLineWidth(0.6); doc.line(MX,y,PW-MX,y); y+=8;
  doc.setFont('helvetica','bold'); doc.setFontSize(18); doc.setTextColor(...brandDark);
  doc.text(`Relatório de Desempenho — ${topic}`, MX, y); y+=7;
  doc.setFont('helvetica','normal'); doc.setFontSize(10.5); doc.setTextColor(...muted);
  const today = new Date().toLocaleDateString('pt-BR');
  doc.text(`${currentSimuladoMeta ? currentSimuladoMeta.nome : 'Simulado'} · ${teacher?`Professor(a): ${teacher}`:'Professor(a) não informado'} · Gerado em ${today}`, MX, y); y+=12;

  // KPIs
  const [_, from, to] = TOPIC_RANGES.find(r=>r[0]===topic);
  const withTopic = presentes.filter(s=>s.topicos);
  const t1g = withTopic.filter(s=>s.turma===CEFET_T1_ID);
  const t2g = withTopic.filter(s=>s.turma===CEFET_T2_ID);
  const pAll = topicAvg(topic, withTopic), p1 = topicAvg(topic, t1g), p2 = topicAvg(topic, t2g);
  const weakStudents = withTopic.map(s=>({s, pct: s.topicos[topic]/DEFAULT_TOPIC_TOTALS[topic]*100, n:s.topicos[topic]}))
    .filter(w=>w.pct<50).sort((a,b)=>a.pct-b.pct);

  const kpis = [
    ['Média geral', fmt1(pAll)+'%', ink],
    [turmaLabel(CEFET_T1_ID), fmt1(p1)+'%', [12,138,99]],
    [turmaLabel(CEFET_T2_ID), fmt1(p2)+'%', [140,83,19]],
    ['Abaixo de 50%', String(weakStudents.length)+' alunos', danger],
  ];
  const kw = (PW-2*MX)/4;
  kpis.forEach((k,i)=>{
    const x = MX + i*kw;
    doc.setDrawColor(220,214,194); doc.setFillColor(245,244,235);
    doc.roundedRect(x, y, kw-4, 18, 1.5, 1.5, 'FD');
    doc.setFont('helvetica','normal'); doc.setFontSize(8); doc.setTextColor(...muted);
    doc.text(k[0], x+3, y+6);
    doc.setFont('helvetica','bold'); doc.setFontSize(13); doc.setTextColor(...k[2]);
    doc.text(k[1], x+3, y+14);
  });
  y += 26;

  // Conteúdos cobrados
  checkPage(10);
  doc.setFont('helvetica','bold'); doc.setFontSize(13); doc.setTextColor(...brandDark);
  doc.text('Conteúdos cobrados nesta matéria', MX, y);
  doc.setDrawColor(...ink); doc.setLineWidth(0.4); doc.line(MX, y+2, PW-MX, y+2);
  y += 9;
  contentGroups(topic).forEach(g=>{
    checkPage(10);
    doc.setFont('helvetica','bold'); doc.setFontSize(9.5); doc.setTextColor(...ink);
    doc.text(g.conteudo, MX+3, y);
    const gcolor = g.pct<50?danger:(g.pct<75?[140,83,19]:[12,138,99]);
    doc.setTextColor(...gcolor);
    doc.text(`${fmt1(g.pct)}%`, PW-MX-3, y, {align:'right'});
    y += 4.6;
    doc.setFont('helvetica','normal'); doc.setFontSize(8.5); doc.setTextColor(...muted);
    doc.text(`Questõe${g.qs.length>1?'s':''} ${g.qs.join(', ')}`, MX+3, y);
    y += 6.5;
  });
  y += 3;

  // Questões que mais geraram dúvida
  const qs = [];
  for(let q=from;q<=to;q++) qs.push(q);
  qs.sort((a,b)=>(100-QSTATS[a].correct_pct)-(100-QSTATS[b].correct_pct)).reverse();
  const worstQs = qs.slice(0,5);

  checkPage(10);
  doc.setFont('helvetica','bold'); doc.setFontSize(13); doc.setTextColor(...brandDark);
  doc.text('Questões que mais geraram dúvida', MX, y);
  doc.setDrawColor(...ink); doc.setLineWidth(0.4); doc.line(MX, y+2, PW-MX, y+2);
  y += 9;

  worstQs.forEach(q=>{
    const s = QSTATS[q], c = QCONTENT[q];
    checkPage(28);
    doc.setFont('helvetica','bold'); doc.setFontSize(11); doc.setTextColor(...ink);
    doc.text(`Questão ${q}`, MX+3, y+6);
    doc.setFont('helvetica','bold'); doc.setFontSize(9.5); doc.setTextColor(...danger);
    doc.text(`${fmt1(100-s.correct_pct)}% erraram`, PW-MX-3, y+6, {align:'right'});
    y += 10;
    doc.setFont('helvetica','normal'); doc.setFontSize(9.5); doc.setTextColor(...ink);
    const enunLines = doc.splitTextToSize(c.enunciado.replace(/\n/g,' '), PW-2*MX-6);
    enunLines.forEach(line=>{ checkPage(6); doc.text(line, MX+3, y); y+=4.6; });
    y += 1.5;
    doc.setFont('helvetica','italic'); doc.setFontSize(9); doc.setTextColor(...muted);
    doc.text(`Gabarito: ${c.gabarito})  ·  Só ${fmt1(s.correct_pct)}% acertaram  ·  Erro mais comum: ${s.most_wrong_letter} (${fmt1(s.most_wrong_pct)}%)`, MX+3, y);
    y += 6;
    doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(...ink);
    const justLines = doc.splitTextToSize('Por que é essa: ' + c.justificativa.replace(/<[^>]+>/g,''), PW-2*MX-6);
    justLines.forEach(line=>{ checkPage(6); doc.text(line, MX+3, y); y+=4.4; });
    y += 4;
  });

  // Sugestões pedagógicas
  checkPage(14);
  doc.setFont('helvetica','bold'); doc.setFontSize(13); doc.setTextColor(...brandDark);
  doc.text('Sugestões para conduzir a turma após o simulado', MX, y);
  doc.setDrawColor(...ink); doc.line(MX, y+2, PW-MX, y+2);
  y += 9;
  const tips = generateTips(topic, {pAll, p1, p2, weakStudents, withTopic, worstQs});
  tips.forEach((tip,i)=>{
    checkPage(14);
    doc.setFillColor(245,244,235); doc.setDrawColor(...brand);
    doc.setLineWidth(0.8); doc.line(MX, y-3.5, MX, y+3.5);
    doc.setFont('helvetica','normal'); doc.setFontSize(9.3); doc.setTextColor(...ink);
    const lines = doc.splitTextToSize(tip, PW-2*MX-6);
    lines.forEach((line,li)=>{ checkPage(6); doc.text(line, MX+4, y); y+=4.5; });
    y += 3.5;
  });

  // Todos os alunos — visão completa
  checkPage(14);
  doc.setFont('helvetica','bold'); doc.setFontSize(13); doc.setTextColor(...brandDark);
  doc.text('Todos os alunos — visão completa neste conteúdo', MX, y);
  doc.setDrawColor(...ink); doc.line(MX, y+2, PW-MX, y+2);
  y += 9;

  function fullTable(list, label){
    checkPage(12);
    doc.setFont('helvetica','bold'); doc.setFontSize(11); doc.setTextColor(...brandDark);
    doc.text(label, MX, y); y += 6;
    doc.setFont('helvetica','bold'); doc.setFontSize(8.5); doc.setTextColor(...muted);
    doc.text('ALUNO', MX, y); doc.text('ACERTOS', PW-MX-32, y); doc.text('%', PW-MX-6, y, {align:'right'});
    y += 1.5; doc.setDrawColor(220,214,194); doc.line(MX,y,PW-MX,y); y += 4;
    const sorted = [...list].sort((a,b)=> a.topicos[topic]-b.topicos[topic]);
    sorted.forEach(s=>{
      checkPage(6);
      const n = s.topicos[topic], total = DEFAULT_TOPIC_TOTALS[topic], pct = n/total*100;
      const color = pct<50 ? danger : (pct<75 ? [140,83,19] : [12,138,99]);
      doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(...ink);
      doc.text(s.nome, MX, y);
      doc.setFont('helvetica','bold'); doc.setTextColor(...color);
      doc.text(`${n}/${total}`, PW-MX-32, y);
      doc.text(`${fmt1(pct)}%`, PW-MX-6, y, {align:'right'});
      y += 5;
    });
    y += 4;
  }
  fullTable(t1g, `Turma 1 (${t1g.length} alunos)`);
  fullTable(t2g, `Turma 2 (${t2g.length} alunos)`);

  addFooter();
  doc.save(`relatorio_${topic.toLowerCase().replace(/[^a-z0-9]+/g,'_')}.pdf`);
}
